# ============ 1. 项目整体管理 (Integration Management) ============
INTEGRATION = {
    "area": "项目整体管理",
    "area_en": "Integration Management",
    "records": [
        {"id": "INT-001", "question": "什么是项目章程？它由谁签发？", "standard_answer": "项目章程是由项目启动者或发起人签发的，正式批准项目成立并授权项目经理动用组织资源开展项目活动的文件。它记录了项目的高层级信息，包括项目目的、目标、可衡量成功标准、高层级需求、风险、里程碑、预算等。", "keywords": ["项目章程", "发起人", "启动", "授权", "项目经理"], "process_group": "启动"},
        {"id": "INT-002", "question": "制定项目章程的主要输入有哪些？", "standard_answer": "制定项目章程的输入包括：商业文件（商业论证、效益管理计划）、协议、事业环境因素、组织过程资产。", "keywords": ["项目章程", "输入", "商业论证", "效益管理计划", "协议"], "process_group": "启动"},
        {"id": "INT-003", "question": "项目管理计划包含哪些组成部分？", "standard_answer": "项目管理计划包含10个子管理计划（范围、需求、进度、成本、质量、资源、沟通、风险、采购、相关方）、3个基准（范围、进度、成本）和若干组件（变更管理、配置管理、绩效测量、生命周期、开发方法等）。", "keywords": ["项目管理计划", "子计划", "基准", "范围", "进度", "成本"], "process_group": "规划"},
        {"id": "INT-004", "question": "指导与管理项目工作过程的主要输出是什么？", "standard_answer": "主要输出包括：可交付成果、工作绩效数据、问题日志、变更请求、项目管理计划更新、项目文件更新、组织过程资产更新。", "keywords": ["指导与管理项目工作", "可交付成果", "工作绩效数据", "变更请求", "问题日志"], "process_group": "执行"},
        {"id": "INT-005", "question": "什么是管理项目知识过程？其目的是什么？", "standard_answer": "管理项目知识是使用现有知识并创建新知识，以实现项目目标并使组织从中学习的过程。其目的包括：利用已有组织知识开展项目工作；使用项目产生的知识支持组织运营和未来项目。包含显性知识和隐性知识。", "keywords": ["管理项目知识", "显性知识", "隐性知识", "经验教训"], "process_group": "执行"},
        {"id": "INT-006", "question": "监控项目工作过程的主要活动有哪些？", "standard_answer": "监控项目工作包括跟踪、审查和报告整体项目进展，以实现项目管理计划中确定的绩效目标。主要活动：比较实际与计划绩效、评估绩效以决定是否需要纠正或预防措施、识别新风险并分析跟踪已识别风险、维护项目信息库等。", "keywords": ["监控项目工作", "跟踪", "审查", "报告", "绩效"], "process_group": "监控"},
        {"id": "INT-007", "question": "实施整体变更控制的核心原则是什么？", "standard_answer": "实施整体变更控制是审查所有变更请求、批准变更、管理对可交付成果、组织过程资产、项目文件和项目管理计划的变更，并对变更结果进行沟通的过程。核心原则：所有变更必须经过变更控制委员会(CCB)审批，避免范围蔓延，确保变更的可追溯性。", "keywords": ["整体变更控制", "变更请求", "CCB", "变更控制委员会", "审批"], "process_group": "监控"},
        {"id": "INT-008", "question": "什么是变更控制委员会(CCB)？", "standard_answer": "变更控制委员会(Change Control Board)是一个正式组成的团体，负责审查、评价、批准、推迟或否决项目变更申请。CCB的成员和权限应在配置管理计划和变更管理计划中明确规定。", "keywords": ["变更控制委员会", "CCB", "审查", "批准", "否决"], "process_group": "监控"},
        {"id": "INT-009", "question": "结束项目或阶段过程的主要活动有哪些？", "standard_answer": "结束项目或阶段包括：为正式完成或关闭项目、阶段或合同所开展的活动。主要活动：存档项目信息、完成计划工作、释放组织资源、移交最终产品、收集经验教训、更新组织过程资产、确认未决事项。", "keywords": ["结束项目", "阶段", "经验教训", "组织过程资产", "移交"], "process_group": "收尾"},
        {"id": "INT-010", "question": "项目章程与项目立项书的区别是什么？", "standard_answer": "项目章程是正式批准项目成立的文件，授权项目经理动用资源；项目立项书（商业论证）是论证项目投资合理性的文档，是项目章程的输入。立项书在前，章程在后；立项书回答\"为什么要做\"，章程回答\"授权谁来做\"。", "keywords": ["项目章程", "立项书", "商业论证", "授权", "输入"], "process_group": "启动"},
        {"id": "INT-011", "question": "什么是配置管理？它在项目中的作用是什么？", "standard_answer": "配置管理是确保项目产品描述的正确性和完整性。其作用包括：识别产品或组成部分的功能与物理特征、控制特征的变更、记录并报告变更实施情况、审核是否符合需求。配置管理关注产品属性，变更控制关注项目变更。", "keywords": ["配置管理", "配置项", "变更", "审核", "产品属性"], "process_group": "监控"},
        {"id": "INT-012", "question": "项目管理计划的基准有哪些？", "standard_answer": "项目管理计划的三大基准是：范围基准（项目范围说明书、WBS、WBS词典）、进度基准（经批准的进度模型）、成本基准（经批准且按时间段分配的项目预算）。基准是测量绩效的依据，变更需走变更控制流程。", "keywords": ["基准", "范围基准", "进度基准", "成本基准", "绩效测量"], "process_group": "规划"},
        {"id": "INT-013", "question": "工作绩效数据、工作绩效信息和工作绩效报告的区别？", "standard_answer": "工作绩效数据是执行过程中产生的最原始观察结果（如计划10小时实际12小时）；工作绩效信息是对数据分析后形成的有意义的结果（如进度偏差-2小时）；工作绩效报告是为决策编制的电子或实体文件。数据→信息→报告是逐层加工的过程。", "keywords": ["工作绩效数据", "工作绩效信息", "工作绩效报告", "绩效"], "process_group": "监控"},
        {"id": "INT-014", "question": "什么是纠正措施、预防措施和缺陷补救？", "standard_answer": "纠正措施是为使项目工作绩效与项目管理计划一致而开展的有目的的活动；预防措施是确保项目工作未来绩效符合项目管理计划的有目的活动；缺陷补救是为修正不一致产品或产品组件而进行的有目的活动。三者都属于变更请求。", "keywords": ["纠正措施", "预防措施", "缺陷补救", "变更请求"], "process_group": "监控"},
        {"id": "INT-015", "question": "项目整体管理的作用和重要性是什么？", "standard_answer": "项目整体管理是识别、定义、组合、统一与协调各项目管理过程组活动的过程。其重要性在于：统一协调范围、进度、成本、质量等各知识领域，处理不同目标间的冲突与权衡，确保项目目标的实现。整体管理是项目管理的核心。", "keywords": ["整体管理", "统一", "协调", "权衡", "核心"], "process_group": "启动"},
        {"id": "INT-016", "question": "什么是项目生命周期？它与管理过程组的关系？", "standard_answer": "项目生命周期是项目从启动到收尾所经历的一系列阶段。它与管理过程组不同：生命周期是面向阶段（产品导向），过程组是面向管理活动（启动、规划、执行、监控、收尾）。一个阶段可包含所有过程组，一个过程组可跨越多个阶段。", "keywords": ["项目生命周期", "阶段", "过程组", "启动", "收尾"], "process_group": "启动"},
        {"id": "INT-017", "question": "项目经验教训登记册的作用和内容包括什么？", "standard_answer": "经验教训登记册用于记录项目执行中遇到的挑战、问题、风险和机会，以及应对措施和经验。内容包括：情况描述、应对策略、结果、经验教训、建议。在项目或阶段结束时应更新到组织过程资产的经验教训知识库中。", "keywords": ["经验教训登记册", "组织过程资产", "知识库", "挑战", "机会"], "process_group": "执行"},
        {"id": "INT-018", "question": "项目管理信息系统(PMIS)的作用是什么？", "standard_answer": "PMIS是由自动化系统和人工程序组成的，用于收集、整合和传播项目管理过程输出的工具。包括进度计划软件、配置管理系统、信息收集与分发系统等。PMIS是指导与管理项目工作和监控项目工作的重要工具。", "keywords": ["PMIS", "项目管理信息系统", "自动化", "配置管理", "工具"], "process_group": "执行"},
        {"id": "INT-019", "question": "什么是项目的假设日志？", "standard_answer": "假设日志用于记录项目整个生命周期中的所有假设条件和制约因素。在制定项目章程时开始记录高层级的假设和制约因素，随着项目进展不断细化和补充。假设日志是整体管理的重要项目文件。", "keywords": ["假设日志", "假设条件", "制约因素", "项目章程"], "process_group": "启动"},
        {"id": "INT-020", "question": "变更请求的审批流程是怎样的？", "standard_answer": "变更请求审批流程：1)提出变更请求；2)记录变更请求；3)评估变更对范围、进度、成本、质量等的影响；4)提交CCB审批；5)CCB批准/否决/推迟；6)若批准则更新计划和基准并实施变更；7)记录变更结果并通知相关方。", "keywords": ["变更请求", "审批流程", "评估", "CCB", "基准更新"], "process_group": "监控"},
        {"id": "INT-021", "question": "项目整体变更控制与配置控制的关系？", "standard_answer": "配置控制是整体变更控制的一部分，专注于产品组成部分的特征和变更。整体变更控制范围更广，涵盖项目所有变更（如进度、成本、过程变更）。配置控制聚焦产品级别，整体变更控制聚焦项目级别，两者协同工作。", "keywords": ["整体变更控制", "配置控制", "产品", "项目", "协同"], "process_group": "监控"},
        {"id": "INT-022", "question": "项目管理计划是否可以更新？更新需经过什么流程？", "standard_answer": "项目管理计划可以更新。任何对基准的更新必须经过实施整体变更控制流程，由CCB审批通过后方可更新。非基准组件的更新也需遵循变更管理计划的规定。更新后的计划需通知相关方。", "keywords": ["项目管理计划", "更新", "基准", "整体变更控制", "CCB"], "process_group": "监控"},
        {"id": "INT-023", "question": "什么是项目工作说明书(SOW)？它用于什么场景？", "standard_answer": "项目工作说明书(Statement of Work)是对项目产品、服务或成果的叙述性描述。SOW主要用于采购场景，作为制定采购文件和协议的输入。内部项目SOW由发起人提供，外部项目SOW由客户提供。SOW包含业务需要、产品范围描述、战略计划。", "keywords": ["SOW", "工作说明书", "采购", "产品范围", "业务需要"], "process_group": "启动"},
        {"id": "INT-024", "question": "项目的商业论证在项目生命周期中如何使用？", "standard_answer": "商业论证用于论证项目投资合理性。在项目启动时作为制定项目章程的输入；在项目执行过程中需定期审核以确认项目持续合理性；若商业论证不再有效，项目可能被终止。项目经理负责确保项目交付的成果符合商业论证。", "keywords": ["商业论证", "投资", "项目章程", "合理性", "终止"], "process_group": "启动"},
        {"id": "INT-025", "question": "项目结束时需要移交哪些内容给运营部门？", "standard_answer": "项目结束时需移交：最终产品/服务/成果、项目文档、操作维护手册、培训资料、经验教训、未决事项清单、保修信息。移交应在相关方之间正式确认并签署交接文件，确保运营部门能正常接收和维护。", "keywords": ["结束项目", "移交", "运营", "文档", "经验教训"], "process_group": "收尾"},
        {"id": "INT-026", "question": "什么是阶段关口？它的作用是什么？", "standard_answer": "阶段关口是项目阶段结束时的审查点，也称为阶段审查、阶段门、里程碑审查、阶段关卡。作用是在阶段结束时评估项目是否应继续、调整或终止，验证阶段可交付成果是否符合验收标准，决定是否进入下一阶段。", "keywords": ["阶段关口", "阶段审查", "里程碑", "验收", "终止"], "process_group": "监控"},
        {"id": "INT-027", "question": "项目提前终止时应如何处理？", "standard_answer": "项目提前终止时仍需走结束项目或阶段过程。需：1)查明终止原因并记录；2)将已完成和未完成的可交付成果移交或处置；3)结算合同；4)收集经验教训；5)更新组织过程资产；6)释放资源；7)通知相关方。", "keywords": ["提前终止", "结束项目", "经验教训", "结算", "资源释放"], "process_group": "收尾"},
        {"id": "INT-028", "question": "项目管理计划与项目文件的区别？", "standard_answer": "项目管理计划是描述项目执行、监控和收尾方式的综合文档，包含子计划和基准。项目文件是项目执行过程中产生的不属于项目管理计划的各种文件，如假设日志、问题日志、风险登记册、经验教训登记册等。两者共同支撑项目管理。", "keywords": ["项目管理计划", "项目文件", "子计划", "基准", "登记册"], "process_group": "规划"},
        {"id": "INT-029", "question": "什么是整体变更控制中的变更日志？", "standard_answer": "变更日志用于记录项目执行过程中发生的所有变更，包括变更请求的提出、审批状态（批准/否决/推迟）、实施情况。变更日志是整体变更控制过程的重要输出，帮助项目团队跟踪变更历史，保证可追溯性。", "keywords": ["变更日志", "变更请求", "审批", "可追溯", "记录"], "process_group": "监控"},
        {"id": "INT-030", "question": "项目经理在项目整体管理中的核心职责是什么？", "standard_answer": "项目经理在整体管理中的核心职责：1)制定项目章程和项目管理计划；2)指导与管理项目执行；3)管理项目知识；4)监控项目工作绩效；5)实施整体变更控制；6)结束项目或阶段。项目经理是项目整体协调与决策的核心。", "keywords": ["项目经理", "整体管理", "项目章程", "指导", "监控", "变更控制"], "process_group": "启动"},
    ]
}

# ============ 2. 项目范围管理 (Scope Management) ============
SCOPE = {
    "area": "项目范围管理",
    "area_en": "Scope Management",
    "records": [
        {"id": "SCO-001", "question": "什么是项目范围？它与产品范围有何区别？", "standard_answer": "项目范围是为交付具有规定特性与功能的产品、服务或成果而必须完成的工作。产品范围是产品、服务或成果的特征和功能。项目范围以工作内容衡量（是否完成所有工作），产品范围以需求衡量（是否满足产品特征）。", "keywords": ["项目范围", "产品范围", "工作", "需求", "区别"], "process_group": "规划"},
        {"id": "SCO-002", "question": "范围管理计划的内容包括哪些？", "standard_answer": "范围管理计划是项目管理计划的组成部分，描述如何定义、制定、监督、控制和确认项目范围。内容包括：制定详细项目范围说明书的方法、创建WBS的方法、范围确认与控制的方法、范围基准维护与批准的方法。", "keywords": ["范围管理计划", "范围说明书", "WBS", "范围确认", "范围控制"], "process_group": "规划"},
        {"id": "SCO-003", "question": "收集需求的方法有哪些？", "standard_answer": "收集需求的方法包括：访谈、焦点小组、引导式研讨会、头脑风暴、问卷调查、标杆对照、原型法、观察、系统交互图、亲和图等。数据表现有亲和图和思维导图。需根据项目特点选择合适方法。", "keywords": ["收集需求", "访谈", "头脑风暴", "问卷调查", "原型法", "引导式研讨会"], "process_group": "规划"},
        {"id": "SCO-004", "question": "什么是需求文件？它包含哪些内容？", "standard_answer": "需求文件描述各种单一需求如何满足项目相关的业务需求。包含：业务需求、相关方需求、解决方案需求（功能和非功能需求）、过渡和就绪需求、项目需求、质量需求。需求文件是定义范围和创建WBS的输入。", "keywords": ["需求文件", "业务需求", "相关方需求", "解决方案需求", "质量需求"], "process_group": "规划"},
        {"id": "SCO-005", "question": "需求跟踪矩阵的作用是什么？", "standard_answer": "需求跟踪矩阵是把产品需求从来源连接到可交付成果的一种表格。作用包括：确保每个需求都有商业价值、跟踪需求状态、监控需求变更、确保需求被满足。它把需求与项目目标、WBS、设计、测试用例关联起来。", "keywords": ["需求跟踪矩阵", "可交付成果", "商业价值", "变更", "关联"], "process_group": "规划"},
        {"id": "SCO-006", "question": "什么是项目范围说明书？它包含哪些内容？", "standard_answer": "项目范围说明书是对项目范围、主要可交付成果、假设条件和制约因素的详细描述。内容包括：产品范围描述、可交付成果、验收标准、项目除外责任、假设条件、制约因素。它明确项目做什么和不做什么。", "keywords": ["范围说明书", "可交付成果", "验收标准", "除外责任", "假设条件"], "process_group": "规划"},
        {"id": "SCO-007", "question": "什么是工作分解结构(WBS)？", "standard_answer": "WBS是对项目团队为实现项目目标、创建可交付成果所需工作的层次化分解。WBS最底层是工作包，是估算成本和进度、分配责任的基础。WBS以可交付成果为导向，遵循100%原则（子层级工作总和等于父层级）。", "keywords": ["WBS", "工作分解结构", "工作包", "可交付成果", "100%原则"], "process_group": "规划"},
        {"id": "SCO-008", "question": "WBS词典的作用和内容是什么？", "standard_answer": "WBS词典是针对每个WBS组件（尤其是工作包）的详细描述文件。内容包括：工作包编码、工作描述、负责组织、进度里程碑、进度活动、资源需求、成本估算、质量要求、验收标准、技术参考文献、合同信息。", "keywords": ["WBS词典", "工作包", "成本估算", "验收标准", "资源需求"], "process_group": "规划"},
        {"id": "SCO-009", "question": "什么是范围基准？", "standard_answer": "范围基准是经过批准的范围说明书、WBS和WBS词典。它是项目范围测量的基准，任何对范围基准的变更必须通过整体变更控制流程审批。范围基准是制定项目管理计划和控制范围的重要依据。", "keywords": ["范围基准", "范围说明书", "WBS", "WBS词典", "变更控制"], "process_group": "规划"},
        {"id": "SCO-010", "question": "范围蔓延和镀金的区别是什么？", "standard_answer": "范围蔓延是指未经正式变更控制程序扩大项目范围的现象，通常由客户不断提出新需求导致。镀金是指项目团队主动为产品增加客户未要求的功能以取悦客户。两者都是范围管理失控的表现，都应避免。", "keywords": ["范围蔓延", "镀金", "变更控制", "客户需求", "功能"], "process_group": "监控"},
        {"id": "SCO-011", "question": "确认范围过程的主要作用是什么？", "standard_answer": "确认范围是正式验收已完成的项目可交付成果的过程。其主要作用是使验收过程具有客观性，通过确认每个可交付成果来提高最终产品、服务或成果获得验收的可能性。由客户或发起人正式验收，通常在每个阶段结束时进行。", "keywords": ["确认范围", "验收", "可交付成果", "客户", "客观性"], "process_group": "监控"},
        {"id": "SCO-012", "question": "确认范围与控制质量的区别？", "standard_answer": "确认范围关注可交付成果的验收（是否符合范围要求，由客户验收）；控制质量关注可交付成果的正确性（是否符合质量标准，由项目团队内部检查）。控制质量一般在确认范围之前进行，先确保质量再交付客户验收。", "keywords": ["确认范围", "控制质量", "验收", "正确性", "质量标准"], "process_group": "监控"},
        {"id": "SCO-013", "question": "控制范围过程的主要活动有哪些？", "standard_answer": "控制范围是监督项目和产品的范围状态、管理范围基准变更的过程。主要活动：1)比较实际范围与范围基准；2)识别范围偏差；3)处理范围变更请求；4)更新范围基准和相关文件；5)通知相关方。", "keywords": ["控制范围", "范围基准", "偏差", "变更请求", "范围变更"], "process_group": "监控"},
        {"id": "SCO-014", "question": "什么是范围确认的验收标准？", "standard_answer": "验收标准是可交付成果验收时必须满足的条件，定义在项目范围说明书中。验收标准应具体、可测量、可验证，例如性能指标、功能要求、合规性要求等。验收标准是确认范围过程判断可交付成果是否可接受的依据。", "keywords": ["验收标准", "可交付成果", "可测量", "范围说明书", "确认范围"], "process_group": "监控"},
        {"id": "SCO-015", "question": "什么是分解技术？在创建WBS中如何应用？", "standard_answer": "分解是把项目范围和项目可交付成果划分为更小、更易管理的组件的技术。在创建WBS时：1)识别和分析可交付成果；2)确定WBS结构和编排方法；3)自上而下逐层分解；4)为WBS组件制定标识；5)核实分解程度是否恰当。", "keywords": ["分解", "WBS", "可交付成果", "工作包", "分解程度"], "process_group": "规划"},
        {"id": "SCO-016", "question": "WBS的100%原则是什么？", "standard_answer": "WBS的100%原则是指WBS中所有子层级工作的总和必须100%等于父层级工作，既不能多也不能少。这确保了WBS涵盖了完成项目所需的全部工作，没有遗漏也没有重复。这是创建WBS的基本原则。", "keywords": ["WBS", "100%原则", "子层级", "父层级", "总和"], "process_group": "规划"},
        {"id": "SCO-017", "question": "什么是滚动式规划？", "standard_answer": "滚动式规划是一种迭代式规划技术，对近期要完成的工作进行详细规划，对远期工作在较高层级进行粗略规划。随着项目进展，远期工作逐渐清晰，再进行详细规划。适用于信息不完全或工作复杂的项目。", "keywords": ["滚动式规划", "迭代", "近期", "远期", "详细规划"], "process_group": "规划"},
        {"id": "SCO-018", "question": "项目除外责任的作用是什么？", "standard_answer": "项目除外责任明确说明哪些内容不属于项目范围。其作用是管理相关方期望，避免范围误解和争议。在范围说明书中明确除外责任，可以让相关方清楚项目不做什么，减少后期范围变更请求。", "keywords": ["除外责任", "范围", "相关方期望", "范围变更", "范围说明书"], "process_group": "规划"},
        {"id": "SCO-019", "question": "引导式研讨会在需求收集中的作用？", "standard_answer": "引导式研讨会把主要相关方聚集在一起，通过结构化引导快速定义需求。优点：快速达成共识、识别冲突需求、建立相关方关系。常用的有JAD（联合应用开发）、QFD（质量功能展开）、焦点小组。能加速需求定义。", "keywords": ["引导式研讨会", "相关方", "共识", "JAD", "QFD"], "process_group": "规划"},
        {"id": "SCO-020", "question": "原型法在需求收集中的应用场景？", "standard_answer": "原型法是在需求不明确时，通过构建产品原型渐进明确需求的方法。适用于需求模糊或相关方难以表达需求的项目。原型可以是渐进明细的，从故事板到功能原型。原型法有助于减少需求变更风险。", "keywords": ["原型法", "需求", "渐进明细", "故事板", "需求变更"], "process_group": "规划"},
        {"id": "SCO-021", "question": "什么是标杆对照？", "standard_answer": "标杆对照是将实际或计划的产品、过程和实践与其他可比组织的产品、过程和实践进行对照比较，以便识别最佳实践、产生改进意见，并为绩效考核提供依据。在收集需求和规划质量管理中常用。", "keywords": ["标杆对照", "最佳实践", "改进", "绩效考核", "可比组织"], "process_group": "规划"},
        {"id": "SCO-022", "question": "项目范围变更的常见原因有哪些？", "standard_answer": "范围变更常见原因：1)外部环境变化（政策、市场、法规）；2)需求定义不明确或有误；3)相关方需求变化；4)技术方案调整；5)范围规划不充分；6)错误或遗漏。变更应通过整体变更控制流程处理。", "keywords": ["范围变更", "外部环境", "需求变化", "相关方", "变更控制"], "process_group": "监控"},
        {"id": "SCO-023", "question": "什么是工作绩效信息在范围控制中的应用？", "standard_answer": "在控制范围过程中，工作绩效信息包括范围偏差、范围绩效趋势、完工估算等。这些信息帮助项目经理判断范围执行情况，识别偏差趋势，决定是否需要采取纠正措施。范围绩效信息需向相关方报告。", "keywords": ["工作绩效信息", "范围控制", "范围偏差", "趋势", "纠正措施"], "process_group": "监控"},
        {"id": "SCO-024", "question": "范围管理计划与需求管理计划有何区别？", "standard_answer": "范围管理计划描述如何定义、制定、监督、控制和确认项目范围，关注WBS和范围基准。需求管理计划描述如何分析、记录和管理需求，关注需求的收集、优先级排序、跟踪和变更。两者都是项目管理计划的组成部分。", "keywords": ["范围管理计划", "需求管理计划", "WBS", "需求", "项目管理计划"], "process_group": "规划"},
        {"id": "SCO-025", "question": "项目范围说明书的除外责任如何编写？", "standard_answer": "除外责任应明确列出项目不包含的工作、不交付的成果、不承担的责任。编写时应具体、明确，避免模糊表述。例如：\"本项目不含硬件采购\"、\"不含用户培训\"。除外责任需与相关方确认并记录在范围说明书中。", "keywords": ["除外责任", "范围说明书", "明确", "相关方确认", "不包含"], "process_group": "规划"},
        {"id": "SCO-026", "question": "什么是范围基准的变更影响分析？", "standard_answer": "范围基准变更影响分析是在范围变更请求提出后，评估变更对项目范围、进度、成本、质量、风险、资源等的影响。分析结果作为CCB审批的依据。影响分析应全面、量化，避免只看局部影响而忽略连锁反应。", "keywords": ["范围基准", "变更影响分析", "进度", "成本", "CCB"], "process_group": "监控"},
        {"id": "SCO-027", "question": "工作包的细化程度如何确定？", "standard_answer": "工作包的细化程度应遵循：1)能够准确估算成本和持续时间；2)能够明确责任人；3)能够监控进展。一般原则是工作包持续时间不超过40-80小时（按项目特点调整）。过细增加管理成本，过粗无法有效控制。", "keywords": ["工作包", "细化", "估算", "责任人", "持续时间"], "process_group": "规划"},
        {"id": "SCO-028", "question": "什么是范围确认中被拒绝的可交付成果处理流程？", "standard_answer": "可交付成果在确认范围时被拒绝后：1)记录拒绝原因；2)返回执行过程组进行缺陷补救；3)补救完成后重新进行控制质量检查；4)通过质量检查后再次提交确认范围；5)直到客户正式验收为止。被拒绝的成果不计入完成。", "keywords": ["确认范围", "拒绝", "可交付成果", "缺陷补救", "控制质量"], "process_group": "监控"},
        {"id": "SCO-029", "question": "范围管理中如何防止范围蔓延？", "standard_answer": "防止范围蔓延的方法：1)制定详细的范围说明书和WBS；2)建立变更控制流程并严格执行；3)明确除外责任；4)加强相关方沟通，管理期望；5)定期审查范围执行情况；6)对未授权的工作说\"不\"。", "keywords": ["范围蔓延", "范围说明书", "变更控制", "除外责任", "相关方沟通"], "process_group": "监控"},
        {"id": "SCO-030", "question": "项目范围管理在整个项目中的意义是什么？", "standard_answer": "项目范围管理确保项目做且仅做成功完成项目所需的全部工作。其意义：1)明确项目边界，避免范围蔓延；2)为进度、成本估算提供基础；3)确保可交付成果满足需求；4)管理相关方期望。范围管理是项目成功的基础。", "keywords": ["范围管理", "边界", "范围蔓延", "可交付成果", "相关方期望"], "process_group": "规划"},
    ]
}

# ============ 3. 项目进度管理 (Schedule Management) ============
SCHEDULE = {
    "area": "项目进度管理",
    "area_en": "Schedule Management",
    "records": [
        {"id": "SCH-001", "question": "项目进度管理包含哪些过程？", "standard_answer": "项目进度管理包含6个过程：1)规划进度管理；2)定义活动；3)排列活动顺序；4)估算活动持续时间；5)制定进度计划；6)控制进度。前5个属于规划过程组，控制进度属于监控过程组。", "keywords": ["进度管理", "规划进度", "定义活动", "排列顺序", "估算持续时间", "控制进度"], "process_group": "规划"},
        {"id": "SCH-002", "question": "什么是里程碑？它在进度计划中的作用？", "standard_answer": "里程碑是项目进度中的一个重要时间点或事件，持续时间通常为零。作用：1)标记重要事件或可交付成果完成；2)作为阶段关口审查点；3)便于向管理层和相关方报告进展；4)帮助识别关键路径。", "keywords": ["里程碑", "时间点", "阶段关口", "进展报告", "关键路径"], "process_group": "规划"},
        {"id": "SCH-003", "question": "什么是关键路径法(CPM)？", "standard_answer": "关键路径法是用于确定项目最短完工时间的方法。关键路径是项目网络图中总持续时间最长的路径，决定了项目的最早完工时间。关键路径上的活动称为关键活动，其总浮动时间为零。任何关键活动延误都会导致项目延期。", "keywords": ["关键路径", "CPM", "最长路径", "总浮动时间", "关键活动"], "process_group": "规划"},
        {"id": "SCH-004", "question": "什么是总浮动时间和自由浮动时间？", "standard_answer": "总浮动时间(TF)是活动在不延误项目完工时间或违反进度制约因素下可以延误的时间，TF=LF-EF或LS-ES。自由浮动时间(FF)是活动在不延误任何紧后活动最早开始时间下可以延误的时间，FF=min(ES后继)-EF本活动。", "keywords": ["总浮动时间", "自由浮动时间", "TF", "FF", "延误"], "process_group": "规划"},
        {"id": "SCH-005", "question": "关键链法(CCM)与关键路径法(CPM)的区别？", "standard_answer": "关键链法考虑资源约束，引入缓冲管理。区别：1)CPM基于无限资源假设，CCM考虑资源约束；2)CPM用浮动时间管理，CCM用缓冲（项目缓冲、接驳缓冲）管理；3)CCM将安全时间集中放在缓冲而非每个活动；4)CCM通过监控缓冲消耗来控制进度。", "keywords": ["关键链", "CCM", "CPM", "资源约束", "缓冲", "项目缓冲"], "process_group": "规划"},
        {"id": "SCH-006", "question": "估算活动持续时间的方法有哪些？", "standard_answer": "估算方法包括：1)类比估算（基于历史类似项目）；2)参数估算（基于历史数据和参数）；3)自下而上估算（WBS各工作包汇总）；4)三点估算（PERT：最乐观O、最可能M、最悲观P）。三角分布Beta=(O+4M+P)/6。", "keywords": ["估算持续时间", "类比估算", "参数估算", "自下而上", "三点估算", "PERT"], "process_group": "规划"},
        {"id": "SCH-007", "question": "三点估算的PERT公式是什么？", "standard_answer": "PERT三点估算公式：期望持续时间=(最乐观时间O+4×最可能时间M+最悲观时间P)/6。标准差σ=(P-O)/6。方差σ²=((P-O)/6)²。PERT基于Beta分布，比三角分布(O+M+P)/3更偏向最可能值，更常用。", "keywords": ["PERT", "三点估算", "最乐观", "最可能", "最悲观", "标准差"], "process_group": "规划"},
        {"id": "SCH-008", "question": "什么是进度压缩？有哪两种方法？", "standard_answer": "进度压缩是在不改变项目范围的情况下缩短项目进度。两种方法：1)赶工：通过增加资源以缩短关键活动持续时间，会增加成本；2)快速跟进：将原来顺序执行的活动并行执行，会增加风险和返工。两者都有适用前提和代价。", "keywords": ["进度压缩", "赶工", "快速跟进", "并行", "资源"], "process_group": "规划"},
        {"id": "SCH-009", "question": "什么是进度基准？如何制定？", "standard_answer": "进度基准是经过批准的进度模型，用于测量项目进度绩效。制定步骤：1)定义活动；2)排列活动顺序；3)估算资源；4)估算持续时间；5)制定进度计划并经相关方批准。进度基准变更需经整体变更控制审批。", "keywords": ["进度基准", "进度模型", "测量", "绩效", "变更控制"], "process_group": "规划"},
        {"id": "SCH-010", "question": "什么是甘特图（横道图）？", "standard_answer": "甘特图是以时间为横轴、活动为纵轴，用横条表示活动开始和结束时间的进度计划图。优点：直观、易于理解、便于沟通。缺点：难以显示活动间的逻辑关系（除非与网络图结合）。是项目进度展示和跟踪的常用工具。", "keywords": ["甘特图", "横道图", "横轴", "直观", "沟通"], "process_group": "监控"},
        {"id": "SCH-011", "question": "什么是进度网络图？有哪些绘制方法？", "standard_answer": "进度网络图是表示项目活动之间逻辑关系的图。绘制方法：1)紧前关系绘图法(PDM/AON)：节点表示活动，箭线表示关系；2)箭线绘图法(ADM/AOA)：箭线表示活动，节点表示事件。PDM更常用，支持四种逻辑关系。", "keywords": ["网络图", "PDM", "ADM", "AON", "AOA", "逻辑关系"], "process_group": "规划"},
        {"id": "SCH-012", "question": "PDM的四种依赖关系是什么？", "standard_answer": "PDM(紧前关系绘图法)四种依赖关系：1)完成-开始(FS)：紧前完成才能开始紧后（最常用）；2)开始-开始(SS)：紧前开始才能开始紧后；3)完成-完成(FF)：紧前完成才能完成紧后；4)开始-完成(SF)：紧前开始才能完成紧后（最少用）。", "keywords": ["PDM", "依赖关系", "FS", "SS", "FF", "SF"], "process_group": "规划"},
        {"id": "SCH-013", "question": "什么是提前量和滞后量？", "standard_answer": "提前量是相对于紧前活动，紧后活动可以提前的时间量，如FS-2天表示紧后可在紧前完成前2天开始。滞后量是紧后活动需要推迟的时间量，如FS+3天表示紧前完成后3天紧后才开始。提前量和滞后量用于精确描述活动关系。", "keywords": ["提前量", "滞后量", "紧前活动", "紧后活动", "依赖关系"], "process_group": "规划"},
        {"id": "SCH-014", "question": "什么是资源平衡和资源平滑？", "standard_answer": "资源平衡是为解决资源冲突，通过调整开始和结束时间使资源需求不超过资源限制，可能延长关键路径。资源平滑是在自由浮动时间和总浮动时间内调整活动，使资源使用更均衡，不影响关键路径。平衡可能延长工期，平滑不延长。", "keywords": ["资源平衡", "资源平滑", "资源冲突", "浮动时间", "关键路径"], "process_group": "规划"},
        {"id": "SCH-015", "question": "控制进度过程的主要活动有哪些？", "standard_answer": "控制进度活动：1)判断项目进度的当前状态；2)对引起进度变更的因素施加影响；3)重新考虑进度管理计划；4)确定进度是否已发生变更；5)管理实际变更。通过比较实际与计划，识别偏差并采取纠正措施。", "keywords": ["控制进度", "当前状态", "进度变更", "偏差", "纠正措施"], "process_group": "监控"},
        {"id": "SCH-016", "question": "什么是进度绩效指标(SPI)？", "standard_answer": "进度绩效指数SPI=挣值EV/计划价值PV。SPI>1表示进度超前，SPI=1表示符合计划，SPI<1表示进度落后。SPI是挣值管理(EVM)的重要指标，用于衡量项目进度执行效率。常与成本绩效指数CPI结合分析。", "keywords": ["SPI", "进度绩效指数", "挣值", "EV", "PV", "EVM"], "process_group": "监控"},
        {"id": "SCH-017", "question": "什么是进度偏差(SV)？", "standard_answer": "进度偏差SV=挣值EV-计划价值PV。SV>0表示进度超前，SV=0表示符合计划，SV<0表示进度落后。SV以货币单位表示进度偏差，是挣值管理的重要指标，用于量化进度偏差程度。", "keywords": ["SV", "进度偏差", "挣值", "EV", "PV", "EVM"], "process_group": "监控"},
        {"id": "SCH-018", "question": "类比估算和参数估算的区别？", "standard_answer": "类比估算是基于历史类似项目的数据进行估算，是粗略的、自上而下的估算，适用于信息不足时。参数估算是基于历史数据和参数（如每平方米造价）进行估算，更准确，需要可靠的历史数据和统计关系。类比是定性对比，参数是定量计算。", "keywords": ["类比估算", "参数估算", "历史数据", "自上而下", "参数"], "process_group": "规划"},
        {"id": "SCH-019", "question": "什么是敏捷进度管理？", "standard_answer": "敏捷进度管理基于迭代和增量开发。使用待办列表、迭代（Sprint）、燃尽图、看板等工具。不依赖详细的甘特图，而是通过短周期迭代持续交付。发布计划→迭代计划→每日站会→迭代评审→迭代回顾，进度通过完成的故事点衡量。", "keywords": ["敏捷", "迭代", "待办列表", "燃尽图", "看板", "故事点"], "process_group": "规划"},
        {"id": "SCH-020", "question": "什么是燃尽图和燃起图？", "standard_answer": "燃尽图显示剩余工作量随时间减少的趋势，用于跟踪迭代或发布进度。燃起图显示已完成工作量和总工作量的变化趋势。燃尽图关注\"还剩多少\"，燃起图关注\"已完成多少\"和\"范围变化\"。两者都是敏捷进度跟踪的可视化工具。", "keywords": ["燃尽图", "燃起图", "剩余工作", "迭代", "可视化"], "process_group": "监控"},
        {"id": "SCH-021", "question": "什么是项目进度中的强制依赖关系？", "standard_answer": "强制依赖关系是法律或合同要求的，或工作的内在性质决定的依赖关系，又称硬逻辑关系。例如必须先打地基才能建墙。与之相对的是选择性依赖关系（软逻辑），由项目团队根据最佳实践确定。强制依赖关系是排列活动顺序的基础。", "keywords": ["强制依赖", "硬逻辑", "法律", "合同", "内在性质"], "process_group": "规划"},
        {"id": "SCH-022", "question": "选择性依赖关系和外部依赖关系的区别？", "standard_answer": "选择性依赖关系（软逻辑）是项目团队基于经验或最佳实践自行确定的依赖关系，可调整。外部依赖关系是项目活动与非项目活动之间的关系，项目团队无法控制，如等待政府审批。选择性是内部可调，外部是不可控。", "keywords": ["选择性依赖", "外部依赖", "软逻辑", "非项目活动", "不可控"], "process_group": "规划"},
        {"id": "SCH-023", "question": "进度管理计划包含哪些内容？", "standard_answer": "进度管理计划包含：进度模型制定和维护方法、准确度单位、计量单位、进度模型维护方法、控制临界值、绩效测量规则、报告格式、过程描述。它是项目管理计划的组成部分，指导进度管理的执行。", "keywords": ["进度管理计划", "进度模型", "准确度", "控制临界值", "绩效测量"], "process_group": "规划"},
        {"id": "SCH-024", "question": "什么是进度基准的维护？", "standard_answer": "进度基准维护指在项目执行过程中，对进度基准的变更进行管理。任何对进度基准的修改必须经过整体变更控制流程审批。经批准的变更更新基准，并通知相关方。基准维护确保进度绩效测量的基准一致性。", "keywords": ["进度基准", "维护", "变更控制", "审批", "绩效测量"], "process_group": "监控"},
        {"id": "SCH-025", "question": "如何应对项目进度延误？", "standard_answer": "应对进度延误：1)分析延误原因和影响；2)评估是否在关键路径上；3)采用进度压缩（赶工/快速跟进）；4)资源平衡或增加资源；5)调整活动顺序或依赖关系；6)申请范围变更（最后手段）；7)更新进度计划并通知相关方。", "keywords": ["进度延误", "进度压缩", "赶工", "快速跟进", "资源平衡"], "process_group": "监控"},
        {"id": "SCH-026", "question": "什么是进度数据？", "standard_answer": "进度数据是用于描述和控制进度的信息集合，包括进度里程碑、进度活动、活动属性、活动之间关系等。在监控过程中，进度数据用于更新进度模型，是制定进度计划和控制进度的输入输出。可用作资源直方图展示。", "keywords": ["进度数据", "里程碑", "活动属性", "进度模型", "资源直方图"], "process_group": "规划"},
        {"id": "SCH-027", "question": "项目日历和资源日历的区别？", "standard_answer": "项目日历规定项目可以开展工作的日期和工作时段，影响所有活动。资源日历规定特定资源（人力、设备）可用的工作日期和时段，影响依赖该资源的活动。资源日历更细化，针对具体资源；项目日历是全局性的。", "keywords": ["项目日历", "资源日历", "工作日期", "资源可用", "时段"], "process_group": "规划"},
        {"id": "SCH-028", "question": "什么是进度变更控制系统？", "standard_answer": "进度变更控制系统是整体变更控制系统的一部分，定义了进度变更的提出、评估、审批、实施和记录流程。包括变更申请表单、审批权限、影响分析要求、文档更新要求等。确保进度变更受控且可追溯。", "keywords": ["进度变更控制", "变更控制系统", "审批", "影响分析", "可追溯"], "process_group": "监控"},
        {"id": "SCH-029", "question": "关键路径在项目进度控制中如何监控？", "standard_answer": "监控关键路径：1)持续跟踪关键活动进展；2)关注关键活动延误（无浮动时间）；3)分析关键路径变化（非关键活动延误可能成为关键）；4)确保关键活动资源到位；5)及时采取纠正措施。关键路径决定项目工期，需重点关注。", "keywords": ["关键路径", "监控", "关键活动", "浮动时间", "纠正措施"], "process_group": "监控"},
        {"id": "SCH-030", "question": "进度管理的意义和目标是什么？", "standard_answer": "进度管理的意义在于管理项目按时完成的各个过程。目标：1)制定合理的进度计划；2)按时完成项目可交付成果；3)有效监控进度偏差；4)及时采取纠正措施；5)管理相关方对进度的期望。进度管理确保项目按时交付。", "keywords": ["进度管理", "按时完成", "进度计划", "进度偏差", "相关方期望"], "process_group": "规划"},
    ]
}

# ============ 4. 项目成本管理 (Cost Management) ============
COST = {
    "area": "项目成本管理",
    "area_en": "Cost Management",
    "records": [
        {"id": "CST-001", "question": "项目成本管理包含哪些过程？", "standard_answer": "项目成本管理包含4个过程：1)规划成本管理；2)估算成本；3)制定预算；4)控制成本。前3个属于规划过程组，控制成本属于监控过程组。成本管理关注项目成本的全生命周期管理。", "keywords": ["成本管理", "规划成本", "估算成本", "制定预算", "控制成本"], "process_group": "规划"},
        {"id": "CST-002", "question": "什么是成本基准？", "standard_answer": "成本基准是经过批准的、按时间段分配的项目预算，不包括管理储备。它是测量、监督和控制成本绩效的依据。成本基准=工作包估算+应急储备，汇总后加上应急储备形成成本基准。管理储备不纳入基准。", "keywords": ["成本基准", "预算", "应急储备", "管理储备", "绩效测量"], "process_group": "规划"},
        {"id": "CST-003", "question": "应急储备和管理储备的区别？", "standard_answer": "应急储备是针对已识别风险（已知-未知）准备的，包含在成本基准内，由项目经理控制使用。管理储备是针对未识别风险（未知-未知）准备的，不包含在成本基准内，使用前需管理层批准。两者都是应对风险的储备。", "keywords": ["应急储备", "管理储备", "已识别风险", "未识别风险", "成本基准"], "process_group": "规划"},
        {"id": "CST-004", "question": "估算成本的方法有哪些？", "standard_answer": "估算成本方法：1)类比估算（基于历史类似项目）；2)参数估算（基于历史数据参数）；3)自下而上估算（WBS汇总，最准确）；4)三点估算（PERT）。还有专家判断、储备分析、质量成本等工具。", "keywords": ["估算成本", "类比估算", "参数估算", "自下而上", "三点估算"], "process_group": "规划"},
        {"id": "CST-005", "question": "什么是挣值管理(EVM)？", "standard_answer": "挣值管理是综合范围、进度和成本测量项目绩效的方法。三个基本指标：计划价值PV（计划工作的预算）、挣值EV（已完工作的预算）、实际成本AC（已完工作的实际成本）。通过这三个指标计算各种偏差和绩效指数。", "keywords": ["EVM", "挣值管理", "PV", "EV", "AC", "绩效"], "process_group": "监控"},
        {"id": "CST-006", "question": "成本偏差(CV)和成本绩效指数(CPI)如何计算？", "standard_answer": "成本偏差CV=挣值EV-实际成本AC。CV>0表示成本节约，CV<0表示成本超支。成本绩效指数CPI=挣值EV/实际成本AC。CPI>1表示成本节约，CPI=1表示符合预算，CPI<1表示成本超支。CPI是成本效率的相对指标。", "keywords": ["CV", "CPI", "成本偏差", "成本绩效指数", "EV", "AC"], "process_group": "监控"},
        {"id": "CST-007", "question": "什么是完工估算(EAC)？有哪些计算公式？", "standard_answer": "完工估算EAC是完成所有工作所需的预期总成本。常见公式：1)EAC=BAC/CPI（按当前效率）；2)EAC=AC+(BAC-EV)（剩余按计划）；3)EAC=AC+(BAC-EV)/(CPI×SPI)（考虑进度和成本效率）；4)EAC=AC+自下而上ETC。", "keywords": ["EAC", "完工估算", "BAC", "CPI", "ETC", "公式"], "process_group": "监控"},
        {"id": "CST-008", "question": "完工尚需估算(ETC)和完工尚需绩效指数(TCPI)是什么？", "standard_answer": "ETC是完成剩余工作预计还需的成本，ETC=EAC-AC。TCPI是完工尚需绩效指数，指为达到特定管理目标，剩余工作必须达到的成本效率。基于BAC：TCPI=(BAC-EV)/(BAC-AC)；基于EAC：TCPI=(BAC-EV)/(EAC-AC)。", "keywords": ["ETC", "TCPI", "完工尚需估算", "完工尚需绩效指数", "BAC", "EAC"], "process_group": "监控"},
        {"id": "CST-009", "question": "什么是完工偏差(VAC)？", "standard_answer": "完工偏差VAC=完工预算BAC-完工估算EAC。VAC>0表示预计总成本低于预算（节约），VAC<0表示预计总成本超过预算（超支）。VAC是预测项目最终成本偏差的指标，帮助管理层决策。", "keywords": ["VAC", "完工偏差", "BAC", "EAC", "预算", "超支"], "process_group": "监控"},
        {"id": "CST-010", "question": "成本管理计划包含哪些内容？", "standard_answer": "成本管理计划包含：计量单位、精确度、准确度、组织程序链接、控制临界值、绩效测量规则（EVM规则、挣值规则）、报告格式、过程描述。它是项目管理计划组成部分，指导成本管理的执行。", "keywords": ["成本管理计划", "计量单位", "精确度", "控制临界值", "EVM规则"], "process_group": "规划"},
        {"id": "CST-011", "question": "什么是质量成本(COQ)？包含哪些类型？", "standard_answer": "质量成本是为达到质量要求所花费的成本，包括：一致性成本（预防成本、评估成本）和非一致性成本（内部失败成本、外部失败成本）。预防成本如培训，评估成本如测试，内部失败如返工，外部失败如保修。", "keywords": ["质量成本", "COQ", "一致性成本", "非一致性成本", "预防", "评估", "失败"], "process_group": "规划"},
        {"id": "CST-012", "question": "什么是沉没成本？在项目决策中如何对待？", "standard_answer": "沉没成本是已经发生且无法收回的成本。在项目决策中，沉没成本不应影响未来决策（不应因已投入大量资金就继续亏损项目）。决策应基于未来收益与成本的比较。这是PMP考试的重要决策原则。", "keywords": ["沉没成本", "决策", "已发生", "无法收回", "未来收益"], "process_group": "监控"},
        {"id": "CST-013", "question": "成本预算的制定步骤是什么？", "standard_answer": "制定预算步骤：1)汇总各活动或工作包成本估算；2)建立应急储备；3)汇总形成成本基准；4)建立管理储备；5)确定项目预算。项目预算=成本基准+管理储备。成本基准需经相关方批准后生效。", "keywords": ["制定预算", "成本估算", "应急储备", "成本基准", "管理储备", "项目预算"], "process_group": "规划"},
        {"id": "CST-014", "question": "什么是资金限制平衡？", "standard_answer": "资金限制平衡是应对组织对资金支出的限制，通过调整进度计划来平衡资金支出。如果资金有季度或年度限制，需调整工作安排使资金支出符合限制。可能需要重新安排工作进度或在成本基准中设置限制。", "keywords": ["资金限制平衡", "资金支出", "进度计划", "成本基准", "限制"], "process_group": "规划"},
        {"id": "CST-015", "question": "什么是项目资金需求？", "standard_answer": "项目资金需求是根据成本基准和管理储备确定的，项目各阶段所需的资金。资金需求通常是阶梯状（S曲线）呈现，累计资金需求随时间递增。资金需求=成本基准+管理储备，按阶段或周期提出。", "keywords": ["资金需求", "成本基准", "管理储备", "S曲线", "阶段"], "process_group": "规划"},
        {"id": "CST-016", "question": "控制成本过程的主要活动有哪些？", "standard_answer": "控制成本活动：1)分析成本绩效，识别偏差；2)确定变更原因；3)决定是否采取纠正或预防措施；4)对引起变更的因素施加影响；5)管理成本变更。使用EVM、预测、储备分析等工具。", "keywords": ["控制成本", "成本绩效", "偏差", "纠正措施", "EVM"], "process_group": "监控"},
        {"id": "CST-017", "question": "什么是储备分析在成本控制中的应用？", "standard_answer": "储备分析在控制成本中用于监控应急储备和管理储备的使用情况。随着风险发生消耗应急储备，需评估剩余储备是否充足。若已识别风险未发生，可释放相应储备。管理储备使用需管理层批准。", "keywords": ["储备分析", "应急储备", "管理储备", "风险", "释放"], "process_group": "监控"},
        {"id": "CST-018", "question": "什么是自下而上估算？为什么它最准确？", "standard_answer": "自下而上估算是对WBS各工作包分别估算成本，再逐层汇总形成总成本估算。它最准确因为：1)基于最底层工作包详细估算；2)由最了解工作的人估算；3)减少粗略估算误差。缺点是耗时较长、成本较高。", "keywords": ["自下而上估算", "WBS", "工作包", "准确", "汇总"], "process_group": "规划"},
        {"id": "CST-019", "question": "什么是参数估算？举例说明。", "standard_answer": "参数估算利用历史数据和统计关系进行估算。例如：每平方米造价2000元，1000平方米=200万元；每行代码成本10元，10000行=10万元。参数估算比类比估算更准确，但需要可靠的历史数据和统计关系。", "keywords": ["参数估算", "历史数据", "统计关系", "每平方米", "每行代码"], "process_group": "规划"},
        {"id": "CST-020", "question": "类比估算的优缺点是什么？", "standard_answer": "类比估算优点：1)快速简便；2)成本低；3)适用于信息不足的早期阶段。缺点：1)准确度较低；2)依赖历史数据的相似性；3)估算者经验影响大。类比估算是粗略估算，适用于项目初期或概念阶段。", "keywords": ["类比估算", "优点", "缺点", "快速", "准确度低"], "process_group": "规划"},
        {"id": "CST-021", "question": "什么是成本绩效的S曲线分析？", "standard_answer": "S曲线是累计成本随时间的曲线，因初期和末期增长慢、中期增长快呈S形。在EVM中，PV、EV、AC都可用S曲线表示。通过比较三条S曲线可直观判断进度和成本偏差。S曲线是成本绩效可视化的重要工具。", "keywords": ["S曲线", "累计成本", "PV", "EV", "AC", "可视化"], "process_group": "监控"},
        {"id": "CST-022", "question": "如何处理成本超支？", "standard_answer": "处理成本超支：1)分析超支原因；2)评估超支对项目的影响；3)采取纠正措施（提高效率、削减非关键范围、赶工等）；4)更新成本估算和预算；5)使用应急储备；6)若超支严重申请管理储备或范围变更；7)通知相关方。", "keywords": ["成本超支", "纠正措施", "应急储备", "管理储备", "范围变更"], "process_group": "监控"},
        {"id": "CST-023", "question": "什么是成本变更控制？", "standard_answer": "成本变更控制是整体变更控制的一部分，管理对成本基准的变更。包括：变更申请、影响分析、CCB审批、基准更新、变更记录、通知相关方。成本基准变更必须经过正式审批，未经批准不得超支。", "keywords": ["成本变更控制", "成本基准", "CCB", "审批", "变更申请"], "process_group": "监控"},
        {"id": "CST-024", "question": "什么是机会成本？", "standard_answer": "机会成本是选择某方案而放弃其他方案所损失的最大潜在收益。在项目选择决策中，选择项目A就意味着放弃项目B的收益，B的收益就是A的机会成本。机会成本是项目选择和经济评价的重要概念。", "keywords": ["机会成本", "项目选择", "放弃", "潜在收益", "经济评价"], "process_group": "启动"},
        {"id": "CST-025", "question": "什么是生命周期成本？", "standard_answer": "生命周期成本是项目产品从设计、开发、生产、运营、维护到废弃处置全生命周期的总成本。项目成本只关注项目阶段的成本，生命周期成本关注项目成果的长期成本。在设计阶段考虑生命周期成本可降低总成本。", "keywords": ["生命周期成本", "设计", "开发", "运营", "维护", "总成本"], "process_group": "规划"},
        {"id": "CST-026", "question": "什么是折旧？有哪些方法？", "standard_answer": "折旧是固定资产因使用或过时而价值减少的过程，在成本估算中需考虑。方法：1)直线折旧（每年等额）；2)加速折旧（如双倍余额递减法，前期折旧多）；3)工作量法。加速折旧可在前期减少税负。", "keywords": ["折旧", "直线折旧", "加速折旧", "固定资产", "税负"], "process_group": "规划"},
        {"id": "CST-027", "question": "什么是成本汇总？", "standard_answer": "成本汇总是将各活动或工作包的成本估算逐层汇总到控制账户，最终形成项目成本估算的过程。通常自下而上进行：活动估算→工作包估算→控制账户→项目总估算。成本汇总是制定预算的关键步骤。", "keywords": ["成本汇总", "活动", "工作包", "控制账户", "制定预算"], "process_group": "规划"},
        {"id": "CST-028", "question": "挣值管理中BAC的含义是什么？", "standard_answer": "BAC(Budget at Completion)完工预算是项目全部计划工作的预算总成本，即成本基准的总和。BAC是EVM的基础参数，用于计算各种绩效指标和预测。BAC在项目批准后通常不变，除非发生基准变更。", "keywords": ["BAC", "完工预算", "成本基准", "EVM", "预算总成本"], "process_group": "监控"},
        {"id": "CST-029", "question": "什么是成本风险分析？", "standard_answer": "成本风险分析是评估成本估算的不确定性和风险。通过三点估算、蒙特卡洛模拟等方法评估成本超支的概率和影响。结合应急储备应对已识别风险，管理储备应对未识别风险。成本风险分析是预算制定的依据。", "keywords": ["成本风险", "三点估算", "蒙特卡洛", "应急储备", "管理储备"], "process_group": "规划"},
        {"id": "CST-030", "question": "项目成本管理的目标是什么？", "standard_answer": "项目成本管理目标：1)在批准预算内完成项目；2)准确估算项目成本；3)合理制定成本基准；4)有效监控成本绩效；5)及时识别和纠正成本偏差；6)管理相关方对成本的期望。确保项目资金有效使用，避免超支。", "keywords": ["成本管理", "目标", "预算", "成本绩效", "成本偏差"], "process_group": "规划"},
    ]
}

# ============ 5. 项目质量管理 (Quality Management) ============
QUALITY = {
    "area": "项目质量管理",
    "area_en": "Quality Management",
    "records": [
        {"id": "QLT-001", "question": "项目质量管理包含哪些过程？", "standard_answer": "项目质量管理包含3个过程：1)规划质量管理（识别质量要求和标准并记录）；2)管理质量（把质量计划转化为可执行的质量活动）；3)控制质量（记录执行结果评估绩效和变更）。前1个规划，1个执行，1个监控。", "keywords": ["质量管理", "规划质量", "管理质量", "控制质量"], "process_group": "规划"},
        {"id": "QLT-002", "question": "质量与等级的区别？", "standard_answer": "质量是\"一系列内在特性满足要求的程度\"，等级是\"对用途相同但技术特性不同的产品或服务的级别分类\"。高质量产品不一定高等级（如低等级但无缺陷），高等级产品不一定高质量（如功能多但缺陷多）。项目应达到既定的质量和等级。", "keywords": ["质量", "等级", "特性", "满足要求", "分类"], "process_group": "规划"},
        {"id": "QLT-003", "question": "什么是精确度和准确度？", "standard_answer": "精确度是重复测量结果之间的一致程度（数据集中程度）。准确度是测量值与真实值的接近程度。精确不一定准确（系统偏差），准确不一定精确（数据分散）。质量管理要求既精确又准确。", "keywords": ["精确度", "准确度", "一致性", "真实值", "系统偏差"], "process_group": "规划"},
        {"id": "QLT-004", "question": "什么是规划质量管理？其输出是什么？", "standard_answer": "规划质量管理是识别项目及其可交付成果的质量要求和标准，并书面描述项目将如何证明符合质量要求和标准的过程。输出：质量管理计划、质量测量指标。它是后续管理质量和控制质量的基础。", "keywords": ["规划质量管理", "质量要求", "标准", "质量管理计划", "质量测量指标"], "process_group": "规划"},
        {"id": "QLT-005", "question": "什么是管理质量？它与质量保证的关系？", "standard_answer": "管理质量是把质量计划转化为可执行的质量活动的过程，也称为质量保证(QA)。管理质量关注过程质量，预防缺陷，是面向过程的。包括所有质量保证活动，如过程改进、质量审计、缺陷分析等。属于执行过程组。", "keywords": ["管理质量", "质量保证", "QA", "过程质量", "预防"], "process_group": "执行"},
        {"id": "QLT-006", "question": "什么是控制质量？它与质量控制的区别？", "standard_answer": "控制质量是记录执行结果评估绩效和变更，确定项目可交付成果是否符合质量要求的过程，也称质量控制(QC)。控制质量关注产品质量，识别缺陷，是面向产品的。通过检验、测试等手段验证可交付成果。属于监控过程组。", "keywords": ["控制质量", "质量控制", "QC", "产品质量", "缺陷", "可交付成果"], "process_group": "监控"},
        {"id": "QLT-007", "question": "质量保证(QA)和质量控制(QC)的区别？", "standard_answer": "QA关注过程，预防缺陷，面向未来，是执行过程；QC关注产品，发现缺陷，面向已发生，是监控过程。QA是\"做对的事\"（过程正确），QC是\"做的事对不对\"（结果正确）。QA在产品完成前，QC在产品完成后。", "keywords": ["QA", "QC", "质量保证", "质量控制", "过程", "产品"], "process_group": "执行"},
        {"id": "QLT-008", "question": "质量成本(COQ)的构成？", "standard_answer": "质量成本包括一致性成本和非一致性成本。一致性成本=预防成本（培训、流程改进）+评估成本（测试、检查）。非一致性成本=内部失败成本（返工、废品）+外部失败成本（保修、索赔、声誉损失）。投资预防可降低失败成本。", "keywords": ["质量成本", "COQ", "一致性成本", "非一致性成本", "预防", "评估", "失败成本"], "process_group": "规划"},
        {"id": "QLT-009", "question": "什么是七种基本质量工具？", "standard_answer": "七种基本质量工具（石川七大工具）：1)因果图（鱼骨图）；2)流程图；3)核对单；4)帕累托图；5)直方图；6)控制图；7)散点图。这些工具用于规划和控制质量，是质量管理的基础工具。", "keywords": ["七大工具", "因果图", "鱼骨图", "帕累托图", "控制图", "散点图"], "process_group": "规划"},
        {"id": "QLT-010", "question": "什么是因果图（鱼骨图）？用途？", "standard_answer": "因果图（鱼骨图/石川图）用于分析问题根本原因。将问题放在\"鱼头\"，从人、机、料、法、环、测（6M）等维度分析原因，形成\"鱼骨\"。因果图帮助团队系统性地识别问题根源，是质量分析的常用工具。", "keywords": ["因果图", "鱼骨图", "石川图", "根本原因", "6M"], "process_group": "执行"},
        {"id": "QLT-011", "question": "什么是帕累托图？80/20原则？", "standard_answer": "帕累托图是按问题发生频率降序排列的柱状图加累计百分比折线图。基于80/20原则：80%的问题由20%的原因造成。帕累托图帮助识别需优先解决的关键问题，集中资源解决主要问题，提高质量改进效率。", "keywords": ["帕累托图", "80/20", "频率", "累计百分比", "关键问题"], "process_group": "监控"},
        {"id": "QLT-012", "question": "什么是控制图？如何使用？", "standard_answer": "控制图用于监控过程是否稳定和可预测。设有上控制限(UCL)和下控制限(LCL)及均值中心线。判断异常：1)数据点超出控制限；2)连续7点在同侧（七点法则）；3)连续7点持续上升或下降。控制图用于判断过程是否受控。", "keywords": ["控制图", "UCL", "LCL", "控制限", "七点法则", "稳定"], "process_group": "监控"},
        {"id": "QLT-013", "question": "什么是散点图？用途？", "standard_answer": "散点图是两个变量之间关系的图，每个点代表一个观测值。用于判断两个变量是否相关（正相关、负相关、无相关）。散点图帮助识别质量因素间的关系，如温度与缺陷率的关系。是质量分析的数据工具。", "keywords": ["散点图", "变量", "相关", "正相关", "负相关"], "process_group": "监控"},
        {"id": "QLT-014", "question": "什么是流程图？在质量管理中的作用？", "standard_answer": "流程图是过程步骤的可视化展示，包括输入、活动、决策、输出。在质量管理中用于：1)规划质量时识别可能的质量问题点；2)管理质量时分析过程改进机会；3)控制质量时追溯问题根源。SIPPOC是常用流程图。", "keywords": ["流程图", "过程步骤", "可视化", "质量问题", "SIPPOC"], "process_group": "规划"},
        {"id": "QLT-015", "question": "什么是直方图？用途？", "standard_answer": "直方图是一种显示数据分布的柱状图，将数据按区间分组显示频率。用于展示过程输出的分布形态，判断是否正态分布、是否有偏移。直方图帮助理解过程变异，是质量分析的描述性统计工具。", "keywords": ["直方图", "数据分布", "频率", "正态分布", "变异"], "process_group": "监控"},
        {"id": "QLT-016", "question": "什么是核对单？在质量控制中的作用？", "standard_answer": "核对单(Checklist)是结构化清单，用于核实是否完成了所有要求步骤或是否满足质量要求。在质量控制中用于系统性检查，确保不遗漏。核对单简单有效，但需根据项目特点定制。基于历史经验教训编制。", "keywords": ["核对单", "清单", "核实", "质量要求", "检查"], "process_group": "监控"},
        {"id": "QLT-017", "question": "什么是质量审计？", "standard_answer": "质量审计是独立的结构化审查，确定项目活动是否符合组织和项目政策、过程和程序。质量审计由独立审计师进行，识别良好做法和改进机会，分享良好实践。质量审计是管理质量过程的重要工具。", "keywords": ["质量审计", "独立审查", "政策", "过程", "改进机会"], "process_group": "执行"},
        {"id": "QLT-018", "question": "什么是PDCA循环？", "standard_answer": "PDCA循环（戴明环）是持续改进的模型：Plan计划→Do执行→Check检查→Act行动。通过不断循环实现质量持续改进。PDCA适用于质量管理、过程改进等，是质量管理的基础理念。每个循环都在前一循环基础上提升。", "keywords": ["PDCA", "戴明环", "持续改进", "计划", "执行", "检查", "行动"], "process_group": "执行"},
        {"id": "QLT-019", "question": "什么是全面质量管理(TQM)？", "standard_answer": "全面质量管理是一种管理理念，强调全员参与、持续改进、客户满意。核心原则：1)以客户为中心；2)全员参与；3)过程方法；4)持续改进；5)基于事实决策；6)关系管理。TQM是现代质量管理的基础。", "keywords": ["TQM", "全面质量管理", "持续改进", "客户满意", "全员参与"], "process_group": "执行"},
        {"id": "QLT-020", "question": "什么是六西格玛？", "standard_answer": "六西格玛是一种以减少缺陷为目标的质量改进方法，目标是每百万次机会缺陷不超过3.4(DPMO=3.4)。采用DMAIC（定义、测量、分析、改进、控制）流程。六西格玛强调数据驱动和统计分析，追求过程稳定。", "keywords": ["六西格玛", "缺陷", "DPMO", "DMAIC", "数据驱动"], "process_group": "执行"},
        {"id": "QLT-021", "question": "什么是质量测量指标？举例？", "standard_answer": "质量测量指标是描述项目或产品属性及如何验证的指标。例如：缺陷密度、故障率、可用性、可靠性、吞吐量、响应时间等。质量测量指标是控制质量过程的输入，用于量化评估质量绩效。", "keywords": ["质量测量指标", "缺陷密度", "故障率", "可用性", "可靠性"], "process_group": "规划"},
        {"id": "QLT-022", "question": "什么是缺陷补救？", "standard_answer": "缺陷补救是为修正不一致产品或产品组件而进行的有目的活动。在控制质量发现缺陷后，提出缺陷补救变更请求，经整体变更控制审批后实施。缺陷补救针对已发生的缺陷，是纠正措施的一种。", "keywords": ["缺陷补救", "不一致", "变更请求", "整体变更控制", "纠正措施"], "process_group": "监控"},
        {"id": "QLT-023", "question": "什么是核对单分析？", "standard_answer": "核对单分析是基于核对单进行检查和分析的技术。核对单基于历史经验教训编制，结构化列出检查项。核对单分析帮助团队系统检查质量问题，避免遗漏。在规划和管理质量中使用，核对单需定期更新。", "keywords": ["核对单分析", "核对单", "经验教训", "结构化", "检查项"], "process_group": "执行"},
        {"id": "QLT-024", "question": "什么是标杆对照在质量管理中的应用？", "standard_answer": "标杆对照在质量管理中将项目质量实践与可比项目或组织进行对比，识别最佳实践和改进机会。用于规划质量时设定质量标准，管理质量时识别改进方向。标杆对照是质量改进的参考方法。", "keywords": ["标杆对照", "质量管理", "最佳实践", "改进", "质量标准"], "process_group": "规划"},
        {"id": "QLT-025", "question": "什么是质量管理的预防胜于检查原则？", "standard_answer": "质量管理强调\"质量被规划和设计进来，而不是检查进来\"。预防胜于检查：通过质量规划、过程控制预防缺陷，成本低于事后检查返工。投资预防成本（一致性成本）可大幅降低失败成本（非一致性成本）。", "keywords": ["预防", "检查", "规划", "一致性成本", "失败成本"], "process_group": "规划"},
        {"id": "QLT-026", "question": "什么是统计抽样？在质量控制中的应用？", "standard_answer": "统计抽样是从总体中选取部分样本进行检验，以推断总体质量的方法。适用于大批量产品检验，降低检验成本。需根据统计方法确定样本量和抽样规则。统计抽样需考虑置信水平和可接受质量限。", "keywords": ["统计抽样", "样本", "总体", "检验成本", "置信水平"], "process_group": "监控"},
        {"id": "QLT-027", "question": "什么是质量改进的持续改进理念？", "standard_answer": "持续改进是质量管理的核心原则，通过不断改进过程和产品提升质量。方法包括PDCA循环、Kaizen（改善）、六西格玛等。持续改进需建立改进文化，鼓励全员参与，基于数据和事实决策。", "keywords": ["持续改进", "PDCA", "Kaizen", "六西格玛", "改进文化"], "process_group": "执行"},
        {"id": "QLT-028", "question": "质量管理计划包含哪些内容？", "standard_answer": "质量管理计划包含：项目将采用的质量标准、质量目标、质量保证活动、质量控制活动、质量角色和职责、质量工具、质量程序、质量度量方法。它是项目管理计划组成部分，指导质量管理的执行。", "keywords": ["质量管理计划", "质量标准", "质量目标", "质量保证", "质量控制", "角色职责"], "process_group": "规划"},
        {"id": "QLT-029", "question": "什么是过程改进计划？", "standard_answer": "过程改进计划是质量管理的子计划，描述如何识别和实施过程改进。包含：过程边界、过程配置、过程度量、绩效改进目标。过程改进计划是管理质量过程的输入，旨在提升过程效率和效果。", "keywords": ["过程改进计划", "过程边界", "过程度量", "绩效改进", "效率"], "process_group": "规划"},
        {"id": "QLT-030", "question": "项目质量管理的意义是什么？", "standard_answer": "项目质量管理的意义：1)确保可交付成果满足质量要求；2)提升客户满意度；3)减少返工和失败成本；4)通过预防降低总成本；5)建立持续改进文化。质量是项目成功的基石，质量管理贯穿项目全生命周期。", "keywords": ["质量管理", "意义", "可交付成果", "客户满意", "返工", "持续改进"], "process_group": "规划"},
    ]
}

# ============ 6. 项目资源管理 (Resource Management) ============
RESOURCE = {
    "area": "项目资源管理",
    "area_en": "Resource Management",
    "records": [
        {"id": "RES-001", "question": "项目资源管理包含哪些过程？", "standard_answer": "项目资源管理包含6个过程：1)规划资源管理；2)估算活动资源；3)获取资源；4)建设团队；5)管理团队；6)控制资源。前2个规划，3个执行（获取资源、建设团队、管理团队），1个监控（控制资源）。", "keywords": ["资源管理", "规划资源", "估算资源", "获取资源", "建设团队", "管理团队", "控制资源"], "process_group": "规划"},
        {"id": "RES-002", "question": "什么是资源分解结构(RBS)？", "standard_answer": "资源分解结构是按类别和类型对项目资源进行分层展现的结构。类别如人力、材料、设备、设施；类型如技能水平、等级。RBS用于资源估算和报告，帮助组织了解资源需求。RBS也是风险分解结构的缩写，需区分语境。", "keywords": ["资源分解结构", "RBS", "类别", "类型", "分层", "资源需求"], "process_group": "规划"},
        {"id": "RES-003", "question": "团队建设的五个阶段是什么？", "standard_answer": "塔克曼团队建设五阶段：1)形成(Forming)：团队成员互相认识；2)震荡(Storming)：冲突和分歧出现；3)规范(Norming)：建立规则和信任；4)成熟(Performing)：高效协作；5)解散(Adjourning)：团队解散。阶段可循环或跳跃。", "keywords": ["团队建设", "塔克曼", "形成", "震荡", "规范", "成熟", "解散"], "process_group": "执行"},
        {"id": "RES-004", "question": "什么是责任分配矩阵(RAM)和RACI图？", "standard_answer": "责任分配矩阵(RAM)是展示项目资源对各工作包或活动责任的表格。RACI是常用RAM：R(Responsible)执行、A(Accountable)负责、C(Consulted)咨询、I(Informed)知情。每项活动至少有一个A，避免责任不清。", "keywords": ["RAM", "RACI", "责任分配矩阵", "执行", "负责", "咨询", "知情"], "process_group": "规划"},
        {"id": "RES-005", "question": "什么是组织图和职位描述？", "standard_answer": "组织图和职位描述用于明确项目团队的角色、职责和汇报关系。包括：层级图（组织分解结构OBS）、矩阵图（RACI）、文本格式（职位描述）。通过明确角色和职责，减少冲突，提高团队效率。", "keywords": ["组织图", "职位描述", "OBS", "RACI", "角色", "职责"], "process_group": "规划"},
        {"id": "RES-006", "question": "什么是领导力？项目经理需要哪些领导力？", "standard_answer": "领导力是引导和影响团队实现目标的能力。项目经理需要的领导力：1)愿景和方向；2)激励和鼓舞；3)沟通和倾听；4)决策和判断；5)情商和人际关系；6)变革管理。领导力是项目经理的核心胜任力。", "keywords": ["领导力", "愿景", "激励", "沟通", "情商", "变革管理"], "process_group": "执行"},
        {"id": "RES-007", "question": "项目经理的五种权力是什么？", "standard_answer": "项目经理五种权力：1)正式/职位权力（来自职位）；2)奖励权力（给予奖励）；3)惩罚/强制权力（给予惩罚）；4)专家权力（专业能力）；5)参照/参照权力（个人魅力和关系）。专家和参照权力最有效，正式权力最弱。", "keywords": ["权力", "正式权力", "奖励权力", "惩罚权力", "专家权力", "参照权力"], "process_group": "执行"},
        {"id": "RES-008", "question": "什么是冲突管理？五种冲突解决方法？", "standard_answer": "冲突管理是处理项目团队和相关方之间分歧的过程。五种方法：1)合作/解决问题（双赢，最佳）；2)妥协/调解（各让一步）；3)缓和/包容（求同存异）；4)撤退/回避（暂避）；5)强迫/命令（赢-输，紧急时）。", "keywords": ["冲突管理", "合作", "妥协", "缓和", "撤退", "强迫", "解决"], "process_group": "执行"},
        {"id": "RES-009", "question": "什么是情商(EI)？在项目管理中的作用？", "standard_answer": "情商是识别、评估和管理自己及他人情绪的能力。包括自我认知、自我管理、社会认知、关系管理。在项目管理中，情商帮助项目经理：建立信任、管理冲突、激励团队、有效沟通。情商是领导力的重要组成部分。", "keywords": ["情商", "EI", "自我认知", "自我管理", "社会认知", "关系管理"], "process_group": "执行"},
        {"id": "RES-010", "question": "什么是虚拟团队？管理虚拟团队的挑战？", "standard_answer": "虚拟团队是地理分布、通过技术协作的团队。挑战：1)沟通障碍（时区、语言、文化）；2)信任建立困难；3)协作工具依赖；4)团队凝聚力低。管理需：明确沟通规则、定期视频会议、建立信任、使用协作工具。", "keywords": ["虚拟团队", "地理分布", "沟通障碍", "信任", "协作工具"], "process_group": "执行"},
        {"id": "RES-011", "question": "什么是团队绩效评价？", "standard_answer": "团队绩效评价是对项目团队整体效能的评估，包括：1)个人技能改进；2)团队能力提升；3)团队凝聚力；4)绩效指标达成。通过团队绩效评价识别改进机会，调整团队建设策略。是管理团队过程的输出。", "keywords": ["团队绩效评价", "技能改进", "团队能力", "凝聚力", "绩效指标"], "process_group": "执行"},
        {"id": "RES-012", "question": "什么是获取资源？有哪些方式？", "standard_answer": "获取资源是获取项目所需团队成员、设施、设备、材料等的过程。获取人力资源方式：预分配、谈判、招募、虚拟团队。获取实物资源方式：采购、租赁。获取资源需考虑资源可用性和组织政策。", "keywords": ["获取资源", "预分配", "谈判", "招募", "虚拟团队", "采购"], "process_group": "执行"},
        {"id": "RES-013", "question": "什么是资源日历？", "standard_answer": "资源日历识别每种资源的可用工作日、班次、正常营业时间、节假日等。区分项目日历（全局工作日）和资源日历（特定资源可用时间）。资源日历是获取资源和估算活动资源的输出，用于进度计划。", "keywords": ["资源日历", "可用工作日", "班次", "节假日", "进度计划"], "process_group": "执行"},
        {"id": "RES-014", "question": "什么是控制资源？主要活动有哪些？", "standard_answer": "控制资源是确保实际资源使用符合计划的过程。主要活动：1)监控资源使用情况；2)识别资源偏差；3)处理资源短缺或过剩；4)确保资源可用性；5)管理资源变更。控制资源确保项目资源有效利用。", "keywords": ["控制资源", "监控", "资源使用", "资源偏差", "资源短缺"], "process_group": "监控"},
        {"id": "RES-015", "question": "什么是管理团队？主要活动有哪些？", "standard_answer": "管理团队是跟踪团队绩效、解决问题、管理团队变更的过程。主要活动：1)评估团队绩效；2)解决冲突；3)提供反馈；4)协调变更；5)管理团队文化。管理团队是执行过程，关注团队日常运作。", "keywords": ["管理团队", "团队绩效", "冲突", "反馈", "团队文化"], "process_group": "执行"},
        {"id": "RES-016", "question": "什么是激励理论？马斯洛需求层次？", "standard_answer": "马斯洛需求层次理论将人类需求分为五层：生理需求、安全需求、社交需求、尊重需求、自我实现需求。低层次需求满足后才追求高层次。项目经理应识别团队成员需求层次，采取相应激励措施。", "keywords": ["激励", "马斯洛", "需求层次", "生理", "安全", "社交", "尊重", "自我实现"], "process_group": "执行"},
        {"id": "RES-017", "question": "什么是赫兹伯格双因素理论？", "standard_answer": "赫兹伯格双因素理论：1)保健因素（薪资、工作条件、政策）缺失会导致不满，改善不会产生激励；2)激励因素（成就、认可、成长）存在会产生激励，缺失不会不满。管理者应同时关注两类因素。", "keywords": ["赫兹伯格", "双因素", "保健因素", "激励因素", "不满", "激励"], "process_group": "执行"},
        {"id": "RES-018", "question": "什么是麦克雷格X-Y理论？", "standard_answer": "麦克雷格X-Y理论：X理论假设员工天生懒惰、逃避责任，需强制管理；Y理论假设员工愿意工作、勇于负责，应授权激励。现代管理倾向于Y理论，通过授权和激励发挥员工主动性。项目经理应根据情境灵活应用。", "keywords": ["麦克雷格", "X理论", "Y理论", "懒惰", "授权", "激励"], "process_group": "执行"},
        {"id": "RES-019", "question": "什么是期望理论(弗鲁姆)？", "standard_answer": "弗鲁姆期望理论：激励力=期望值×工具性×效价。期望值是努力达成绩效的概率；工具性是绩效获得奖励的概率；效价是奖励的价值。三者任一为零则激励为零。管理者应确保努力-绩效-奖励-价值的链条通畅。", "keywords": ["期望理论", "弗鲁姆", "期望值", "工具性", "效价", "激励"], "process_group": "执行"},
        {"id": "RES-020", "question": "什么是建设团队？主要活动有哪些？", "standard_answer": "建设团队是提高团队成员胜任力和互动，提升团队绩效的过程。主要活动：1)培训；2)团队建设活动；3)明确角色和职责；4)认可与奖励；5)建立团队文化。建设团队是执行过程，贯穿项目始终。", "keywords": ["建设团队", "培训", "团队建设", "角色", "认可与奖励"], "process_group": "执行"},
        {"id": "RES-021", "question": "什么是认可与奖励？原则？", "standard_answer": "认可与奖励是激励团队的重要手段。原则：1)奖励应与绩效挂钩；2)奖励应公平透明；3)物质奖励与精神奖励结合；4)及时奖励；5)因人而异。奖励应在规划阶段就明确标准和方式，避免临时随意。", "keywords": ["认可与奖励", "绩效", "公平", "及时", "激励"], "process_group": "执行"},
        {"id": "RES-022", "question": "什么是培训？在资源管理中的作用？", "standard_answer": "培训是提升团队成员知识和技能的活动。在建设团队过程中，识别培训需求并安排培训。培训包括正式培训、导师指导、在职培训等。培训可弥补技能差距，提升团队整体能力，是团队建设的重要手段。", "keywords": ["培训", "技能", "知识", "导师", "在职培训"], "process_group": "执行"},
        {"id": "RES-023", "question": "什么是估算活动资源？输入输出？", "standard_answer": "估算活动资源是估算执行活动所需团队资源及类型和数量的过程。输入：资源管理计划、活动清单、活动属性、资源日历等。输出：资源需求、估算依据、资源分解结构。资源估算是制定进度和预算的基础。", "keywords": ["估算活动资源", "资源需求", "估算依据", "资源分解结构", "进度"], "process_group": "规划"},
        {"id": "RES-024", "question": "什么是资源管理计划？包含哪些内容？", "standard_answer": "资源管理计划是关于如何分类、分配、获取、管理和释放项目资源的指南。包含：资源识别、获取资源方法、角色和职责、团队资源管理、培训计划、团队建设方法、认可计划、合规要求。是项目管理计划组成部分。", "keywords": ["资源管理计划", "获取资源", "角色职责", "培训", "团队建设"], "process_group": "规划"},
        {"id": "RES-025", "question": "什么是团队章程？", "standard_answer": "团队章程是记录团队价值观、沟通指南、决策标准、冲突解决过程、会议指南、团队协议的文件。团队章程由团队共同制定，建立团队行为规范。团队章程是规划资源管理的输出，提升团队协作效率。", "keywords": ["团队章程", "价值观", "沟通指南", "决策标准", "冲突解决"], "process_group": "规划"},
        {"id": "RES-026", "question": "什么是预分配？", "standard_answer": "预分配是在项目章程或竞标文件中预先指定项目团队成员或资源的方式。预分配发生在获取资源过程之前，常见于：1)项目章程指定关键人员；2)竞标承诺特定专家。预分配资源需确认可用性。", "keywords": ["预分配", "项目章程", "竞标", "关键人员", "获取资源"], "process_group": "执行"},
        {"id": "RES-027", "question": "什么是谈判在获取资源中的应用？", "standard_answer": "项目经理常需与职能经理、其他项目团队谈判获取资源。谈判要点：1)说明资源需求和价值；2)展示项目优先级；3)灵活处理时间安排；4)寻求双赢。谈判能力是项目经理获取资源的关键技能。", "keywords": ["谈判", "获取资源", "职能经理", "优先级", "双赢"], "process_group": "执行"},
        {"id": "RES-028", "question": "什么是问题解决？步骤？", "standard_answer": "问题解决是识别和解决问题的过程。步骤：1)识别问题（定义问题）；2)分析问题（根本原因）；3)生成解决方案；4)选择最佳方案；5)实施解决方案；6)验证效果。问题日志用于记录和跟踪问题。", "keywords": ["问题解决", "识别", "分析", "根本原因", "解决方案", "问题日志"], "process_group": "执行"},
        {"id": "RES-029", "question": "什么是管理团队中的情商应用？", "standard_answer": "管理团队中应用情商：1)识别团队成员情绪状态；2)同理心理解成员需求；3)管理自身情绪保持冷静；4)调节团队氛围；5)处理人际冲突。情商帮助建立信任和凝聚力，提升团队绩效。是现代项目经理的核心能力。", "keywords": ["情商", "管理团队", "同理心", "情绪", "信任", "凝聚力"], "process_group": "执行"},
        {"id": "RES-030", "question": "项目资源管理的目标是什么？", "standard_answer": "项目资源管理目标：1)获取项目所需资源；2)高效利用资源；3)建设高绩效团队；4)提升团队胜任力；5)有效管理冲突；6)确保资源可用性。资源管理确保项目有合适的资源按时按质完成。", "keywords": ["资源管理", "目标", "获取资源", "高绩效团队", "胜任力"], "process_group": "规划"},
    ]
}

# ============ 7. 项目沟通管理 (Communications Management) ============
COMMUNICATIONS = {
    "area": "项目沟通管理",
    "area_en": "Communications Management",
    "records": [
        {"id": "COM-001", "question": "项目沟通管理包含哪些过程？", "standard_answer": "项目沟通管理包含3个过程：1)规划沟通管理；2)管理沟通；3)监督沟通。规划属于规划过程组，管理沟通属于执行过程组，监督沟通属于监控过程组。沟通管理确保项目信息及时、恰当地生成、收集和处置。", "keywords": ["沟通管理", "规划沟通", "管理沟通", "监督沟通"], "process_group": "规划"},
        {"id": "COM-002", "question": "沟通模型包含哪些要素？", "standard_answer": "基本沟通模型包含：发送方、编码、信息、媒介、噪声、解码、接收方、反馈。发送方编码信息通过媒介传输，接收方解码信息，受噪声干扰。沟通需确认反馈确保理解一致。有效沟通要求信息被接收并正确理解。", "keywords": ["沟通模型", "发送方", "接收方", "编码", "解码", "噪声", "反馈"], "process_group": "规划"},
        {"id": "COM-003", "question": "沟通方式有哪些？", "standard_answer": "沟通方式：1)正式书面（合同、报告）；2)正式口头（演讲、会议）；3)非正式书面（邮件、备忘录）；4)非正式口头（闲聊、电话）。复杂问题用正式书面，简单问题用非正式口头。选择方式需考虑受众、内容、紧急程度。", "keywords": ["沟通方式", "正式书面", "正式口头", "非正式书面", "非正式口头"], "process_group": "规划"},
        {"id": "COM-004", "question": "沟通渠道数的计算公式？", "standard_answer": "沟通渠道数=n×(n-1)/2，n为参与沟通的人数。例如5人团队沟通渠道=5×4/2=10条。随着人数增加，沟通渠道呈指数增长，沟通复杂度急剧上升。控制团队规模可降低沟通复杂度。", "keywords": ["沟通渠道", "公式", "n(n-1)/2", "人数", "复杂度"], "process_group": "规划"},
        {"id": "COM-005", "question": "什么是沟通管理计划？包含哪些内容？", "standard_answer": "沟通管理计划描述如何规划、结构化、执行和监督项目沟通。包含：相关方沟通需求、沟通信息（语言、格式、内容、详细程度）、上报过程、沟通原因、时间频率、发送方和接收方、沟通方法、资源、更新方法。", "keywords": ["沟通管理计划", "沟通需求", "信息", "频率", "沟通方法"], "process_group": "规划"},
        {"id": "COM-006", "question": "什么是管理沟通？主要活动有哪些？", "standard_answer": "管理沟通是及时、正确地生成、收集、分发、存储和处置项目信息的过程。主要活动：1)沟通信息生成；2)信息分发；3)报告绩效；4)维护沟通记录；5)更新沟通管理计划。管理沟通属于执行过程组。", "keywords": ["管理沟通", "生成", "分发", "报告绩效", "沟通记录"], "process_group": "执行"},
        {"id": "COM-007", "question": "什么是监督沟通？主要活动有哪些？", "standard_answer": "监督沟通是确保满足项目及其相关方信息需求的过程。主要活动：1)评估沟通有效性；2)识别沟通问题；3)调整沟通方式；4)更新沟通管理计划；5)通知相关方沟通变更。监督沟通确保沟通持续有效。", "keywords": ["监督沟通", "沟通有效性", "沟通问题", "调整", "沟通管理计划"], "process_group": "监控"},
        {"id": "COM-008", "question": "什么是工作绩效报告？", "standard_answer": "工作绩效报告是为制定决策、采取行动或引起关注而编制的电子或实体文件。包括状态报告、进展报告、预测、挣值报告等。工作绩效报告是管理沟通的输出，向相关方展示项目绩效和进展。", "keywords": ["工作绩效报告", "状态报告", "进展报告", "预测", "挣值报告"], "process_group": "执行"},
        {"id": "COM-009", "question": "什么是有效沟通的原则？", "standard_answer": "有效沟通原则：1)明确目的和受众；2)选择合适的沟通方式；3)确保信息清晰简洁；4)积极倾听；5)确认理解（反馈）；6)考虑文化差异；7)及时沟通；8)维护沟通渠道。有效沟通是项目成功的关键。", "keywords": ["有效沟通", "目的", "受众", "倾听", "反馈", "文化差异"], "process_group": "执行"},
        {"id": "COM-010", "question": "什么是积极倾听？", "standard_answer": "积极倾听是专注于理解发送方信息的沟通技巧。技巧：1)保持专注；2)不打断；3)通过提问澄清；4)复述确认理解；5)注意非语言信息；6)给予反馈。积极倾听能减少误解，建立信任，是沟通管理的核心技能。", "keywords": ["积极倾听", "专注", "提问", "复述", "非语言信息", "反馈"], "process_group": "执行"},
        {"id": "COM-011", "question": "沟通中的噪声有哪些类型？", "standard_answer": "噪声是干扰沟通的因素。类型：1)物理噪声（环境噪音）；2)语义噪声（语言障碍、术语）；3)心理噪声（偏见、情绪）；4)文化噪声（文化差异）；5)技术噪声（设备故障）。识别并消除噪声可提升沟通效果。", "keywords": ["噪声", "物理", "语义", "心理", "文化", "技术"], "process_group": "规划"},
        {"id": "COM-012", "question": "什么是沟通技术？选择考虑因素？", "standard_answer": "沟通技术是用于项目沟通的工具和方法，如邮件、视频会议、协作平台、报告系统。选择考虑因素：1)紧急程度；2)信息可用性；3)技术可用性；4)项目环境；5)信息敏感性和保密性；6)成本。需匹配沟通需求。", "keywords": ["沟通技术", "紧急程度", "可用性", "敏感性", "保密性", "成本"], "process_group": "规划"},
        {"id": "COM-013", "question": "什么是信息管理系统？", "standard_answer": "信息管理系统用于管理项目信息和沟通记录，包括纸质和电子系统。功能：1)存储和检索信息；2)版本控制；3)分发信息；4)权限管理。信息管理系统是管理沟通的工具，支持高效信息管理。", "keywords": ["信息管理系统", "存储", "检索", "版本控制", "权限管理"], "process_group": "执行"},
        {"id": "COM-014", "question": "什么是项目报告？类型？", "standard_answer": "项目报告是向相关方汇报项目状态和进展的文件。类型：1)状态报告（当前状态）；2)进展报告（期间进展）；3)预测报告（未来预测）；4)例外报告（异常情况）；5)综合报告。报告应简洁、准确、及时。", "keywords": ["项目报告", "状态报告", "进展报告", "预测报告", "例外报告"], "process_group": "执行"},
        {"id": "COM-015", "question": "什么是沟通中的非语言沟通？", "standard_answer": "非语言沟通是通过肢体语言、面部表情、语调、眼神、距离等传递信息的方式。研究表明非语言信息占沟通效果的55%以上。项目经理应注意自身非语言信息，并解读相关方的非语言信号，提升沟通效果。", "keywords": ["非语言沟通", "肢体语言", "面部表情", "语调", "眼神"], "process_group": "执行"},
        {"id": "COM-016", "question": "什么是相关方沟通需求分析？", "standard_answer": "相关方沟通需求分析是识别每个相关方或群体需要什么信息、何时需要、如何获取的过程。基于相关方登记册、相关方参与度评估矩阵进行分析。沟通需求分析是规划沟通管理的核心，确保沟通有的放矢。", "keywords": ["沟通需求分析", "相关方登记册", "参与度评估", "信息", "规划沟通"], "process_group": "规划"},
        {"id": "COM-017", "question": "什么是沟通方法？三种类型？", "standard_answer": "三种沟通方法：1)互动沟通（电话、会议、视频，实时双向）；2)推式沟通（邮件、报告，发送方主动推送，不确保接收）；3)拉式沟通（网站、知识库，接收方主动获取）。复杂紧急用互动，大量信息用推/拉式。", "keywords": ["沟通方法", "互动沟通", "推式沟通", "拉式沟通", "实时"], "process_group": "规划"},
        {"id": "COM-018", "question": "什么是沟通中的反馈？重要性？", "standard_answer": "反馈是接收方对发送方信息的回应。重要性：1)确认信息被接收和理解；2)发现沟通偏差；3)促进双向沟通；4)建立信任。有效反馈应及时、具体、建设性。缺乏反馈的沟通是单向的，容易产生误解。", "keywords": ["反馈", "接收", "理解", "双向沟通", "信任"], "process_group": "执行"},
        {"id": "COM-019", "question": "什么是项目沟通中的会议管理？", "standard_answer": "会议管理是规划、组织和执行项目会议的过程。要素：1)明确会议目的和议程；2)邀请合适参会者；3)按时开始结束；4)记录决策和行动项；5)分发会议纪要；6)跟踪行动项。高效会议是沟通管理的关键。", "keywords": ["会议管理", "议程", "参会者", "会议纪要", "行动项"], "process_group": "执行"},
        {"id": "COM-020", "question": "什么是沟通中的跨文化沟通？", "standard_answer": "跨文化沟通是不同文化背景人员之间的沟通。挑战：语言障碍、沟通风格差异、价值观差异、非语言符号差异。策略：1)尊重文化差异；2)使用简单语言；3)确认理解；4)避免文化偏见；5)了解对方文化。", "keywords": ["跨文化沟通", "语言障碍", "价值观", "文化差异", "偏见"], "process_group": "执行"},
        {"id": "COM-021", "question": "什么是沟通记录管理？", "standard_answer": "沟通记录管理是对项目沟通产生的文件、邮件、会议纪要等进行存储、归档和检索的管理。包括：版本控制、权限管理、保留期限、归档规则。良好的沟通记录管理支持信息追溯和组织过程资产积累。", "keywords": ["沟通记录", "存储", "归档", "版本控制", "权限管理"], "process_group": "执行"},
        {"id": "COM-022", "question": "什么是相关方参与度评估矩阵？", "standard_answer": "相关方参与度评估矩阵显示相关方当前参与度与期望参与度的对比。五类参与度：不了解、抵制、中立、支持、领导。通过矩阵识别差距，制定沟通策略提升相关方参与度。是规划沟通和相关方管理的工具。", "keywords": ["参与度评估矩阵", "不了解", "抵制", "中立", "支持", "领导"], "process_group": "规划"},
        {"id": "COM-023", "question": "什么是沟通中的向上沟通？", "standard_answer": "向上沟通是项目经理向高层管理、发起人汇报的沟通。要点：1)简明扼要，突出重点；2)提供数据支持；3)提出问题和解决方案；4)及时报告风险和问题；5)管理期望。向上沟通影响项目资源和支持。", "keywords": ["向上沟通", "高层管理", "发起人", "简明扼要", "解决方案"], "process_group": "执行"},
        {"id": "COM-024", "question": "什么是沟通中的危机沟通？", "standard_answer": "危机沟通是项目发生重大问题或风险时的沟通。原则：1)及时通知相关方；2)透明诚实；3)统一口径；4)提供解决方案；5)持续更新。危机沟通需预先规划，建立危机沟通预案，避免信息混乱。", "keywords": ["危机沟通", "及时", "透明", "统一口径", "预案"], "process_group": "执行"},
        {"id": "COM-025", "question": "什么是项目沟通中的视觉沟通？", "standard_answer": "视觉沟通是使用图表、图形、仪表盘等可视化方式传递信息。优势：1)直观易懂；2)快速传递大量信息；3)突出重点；4)便于记忆。常用工具：甘特图、燃尽图、绩效仪表盘。视觉沟通提升沟通效率。", "keywords": ["视觉沟通", "可视化", "图表", "仪表盘", "直观"], "process_group": "执行"},
        {"id": "COM-026", "question": "什么是沟通中的7C原则？", "standard_answer": "沟通7C原则：1)清晰(Clear)；2)简洁(Concise)；3)具体(Concrete)；4)正确(Correct)；5)连贯(Coherent)；6)完整(Complete)；7)礼貌(Courteous)。遵循7C原则可提升沟通质量和效果。", "keywords": ["7C原则", "清晰", "简洁", "具体", "正确", "完整", "礼貌"], "process_group": "执行"},
        {"id": "COM-027", "question": "什么是项目沟通的信息流向？", "standard_answer": "项目沟通信息流向包括：1)向上（向管理层汇报）；2)向下（向团队成员传达）；3)横向（与同级协调）；4)对外（与客户、供应商沟通）。沟通管理计划应明确各类信息的流向和方式，确保信息畅通。", "keywords": ["信息流向", "向上", "向下", "横向", "对外"], "process_group": "规划"},
        {"id": "COM-028", "question": "什么是沟通中的倾听障碍？", "standard_answer": "倾听障碍影响有效倾听。常见障碍：1)预设立场；2)分心；3)选择性倾听；4)急于回应；5)情绪干扰；6)语言障碍。克服障碍：保持专注、开放心态、延迟评判、确认理解。有效倾听是沟通的基础。", "keywords": ["倾听障碍", "预设立场", "分心", "选择性倾听", "情绪"], "process_group": "执行"},
        {"id": "COM-029", "question": "什么是沟通中的书面沟通技巧？", "standard_answer": "书面沟通技巧：1)结构清晰（金字塔原理）；2)语言简洁；3)用数据说话；4)适当使用图表；5)注意语气；6)校对错误。书面沟通可留存记录，适用于复杂、重要信息。邮件、报告、备忘录是常见形式。", "keywords": ["书面沟通", "金字塔原理", "简洁", "数据", "校对"], "process_group": "执行"},
        {"id": "COM-030", "question": "项目沟通管理的意义是什么？", "standard_answer": "项目沟通管理意义：1)确保信息及时准确传递；2)协调相关方期望和行动；3)减少误解和冲突；4)支持决策制定；5)提升团队协作；6)促进问题解决。项目经理75%-90%时间用于沟通，沟通是项目成功的关键。", "keywords": ["沟通管理", "意义", "信息传递", "相关方", "决策", "团队协作"], "process_group": "规划"},
    ]
}

# ============ 8. 项目采购管理 (Procurement Management) ============
PROCUREMENT = {
    "area": "项目采购管理",
    "area_en": "Procurement Management",
    "records": [
        {"id": "PRC-001", "question": "项目采购管理包含哪些过程？", "standard_answer": "项目采购管理包含3个过程：1)规划采购管理（记录采购决策、明确采购方法、识别潜在卖方）；2)实施采购（获取卖方应答、选择卖方、授予合同）；3)控制采购（管理采购关系、监督合同执行）。前1个规划，2个执行/监控。", "keywords": ["采购管理", "规划采购", "实施采购", "控制采购", "合同"], "process_group": "规划"},
        {"id": "PRC-002", "question": "什么是自制与外购分析？", "standard_answer": "自制与外购分析是决定某项工作、产品或服务由项目团队自行完成还是向外采购的分析。考虑因素：1)成本（直接成本、间接成本）；2)能力；3)时间；4)风险；5)战略。自制与外购分析是规划采购的工具。", "keywords": ["自制与外购", "成本", "能力", "时间", "风险", "战略"], "process_group": "规划"},
        {"id": "PRC-003", "question": "合同有哪些主要类型？", "standard_answer": "合同主要类型：1)总价合同（FFP固定总价、FPIF总价加激励费用、FP-EPA总价加经济价格调整）；2)成本补偿合同（CPFF成本加固定费用、CPIF成本加激励费用、CPAF成本加奖励费用）；3)工料合同(T&M)。", "keywords": ["合同类型", "总价合同", "成本补偿合同", "工料合同", "FFP", "CPFF", "T&M"], "process_group": "规划"},
        {"id": "PRC-004", "question": "固定总价合同(FFP)的特点和适用场景？", "standard_answer": "FFP固定总价合同：卖方以固定价格交付产品，风险由卖方承担。适用场景：1)需求明确；2)工作范围清晰；3)市场成熟。优点：买方成本确定。缺点：卖方可能降低质量，报价较高以覆盖风险。买方风险最低。", "keywords": ["固定总价", "FFP", "风险卖方", "需求明确", "买方风险低"], "process_group": "规划"},
        {"id": "PRC-005", "question": "成本补偿合同的特点和适用场景？", "standard_answer": "成本补偿合同：买方补偿卖方实际成本加约定费用，风险由买方承担。适用场景：1)工作范围不明确；2)高风险项目；3)研发性质。类型：CPFF（成本加固定费用）、CPIF（成本加激励费用）、CPAF（成本加奖励费用）。买方风险高。", "keywords": ["成本补偿", "CPFF", "CPIF", "CPAF", "风险买方", "范围不明确"], "process_group": "规划"},
        {"id": "PRC-006", "question": "工料合同(T&M)的特点和适用场景？", "standard_answer": "工料合同(T&M)：按实际工时和材料计费，兼具总价和成本补偿特点。适用场景：1)工作量和范围不确定；2)小额采购；3)临时人力；4)紧急采购。T&M合同灵活，但需监控避免成本失控。常设上限。", "keywords": ["工料合同", "T&M", "工时", "材料", "灵活", "小额采购"], "process_group": "规划"},
        {"id": "PRC-007", "question": "什么是采购管理计划？包含哪些内容？", "standard_answer": "采购管理计划描述从制定采购文件到合同收尾的采购活动方式。包含：采购方式、合同类型、招标文件、选择标准、供应商管理、协调、采购指标。采购管理计划是项目管理计划组成部分。", "keywords": ["采购管理计划", "采购方式", "合同类型", "招标文件", "选择标准"], "process_group": "规划"},
        {"id": "PRC-008", "question": "什么是采购工作说明书(SOW)？", "standard_answer": "采购工作说明书是对拟采购产品、服务或成果的详细描述。SOW来自项目范围基准，包含：规格、质量要求、数量、交付时间、地点、验收标准。SOW是招标文件的一部分，应清晰、完整、可执行。", "keywords": ["采购SOW", "工作说明书", "规格", "质量要求", "验收标准"], "process_group": "规划"},
        {"id": "PRC-009", "question": "什么是招标文件？有哪些类型？", "standard_answer": "招标文件是用于邀请卖方提交建议书的文件。类型：1)信息邀请书(RFI)（获取信息）；2)报价邀请书(RFQ)（获取报价，用于商品）；3)建议邀请书(RFP)（获取方案，用于复杂采购）。根据采购复杂度选择。", "keywords": ["招标文件", "RFI", "RFQ", "RFP", "建议书", "报价"], "process_group": "规划"},
        {"id": "PRC-010", "question": "什么是供方选择标准？", "standard_answer": "供方选择标准是用于评定卖方建议书的标准。包括：1)能力；2)方法和途径；3)价格；4)财务能力；5)过往经验；6)技术能力；7)管理方法；8)知识转移；9)知识产权。标准可分配权重进行综合评分。", "keywords": ["供方选择标准", "能力", "价格", "经验", "技术能力", "权重"], "process_group": "规划"},
        {"id": "PRC-011", "question": "什么是实施采购？主要活动有哪些？", "standard_answer": "实施采购是获取卖方应答、选择卖方并授予合同的过程。主要活动：1)发布招标文件；2)召开投标人会议；3)接收建议书；4)评审建议书；5)选择卖方；6)授予合同。实施采购属于执行过程组。", "keywords": ["实施采购", "招标", "投标人会议", "建议书", "选择卖方", "授予合同"], "process_group": "执行"},
        {"id": "PRC-012", "question": "什么是投标人会议？", "standard_answer": "投标人会议（承包商会议、供应商会议）是在提交建议书前，买方与所有潜在卖方召开的会议。目的：1)确保所有潜在卖方对采购需求有相同理解；2)回答卖方疑问；3)确保公平。会议记录应分发给所有参与者。", "keywords": ["投标人会议", "承包商会议", "潜在卖方", "理解一致", "公平"], "process_group": "执行"},
        {"id": "PRC-013", "question": "什么是建议书评价技术？", "standard_answer": "建议书评价技术是按供方选择标准评审卖方建议书的方法。常用：1)加权评分法（按标准打分加权汇总）；2)筛选系统（先筛选再评分）；3)独立估算（与买方估算对比）。评价应客观、公正、可追溯。", "keywords": ["建议书评价", "加权评分", "筛选系统", "独立估算", "客观公正"], "process_group": "执行"},
        {"id": "PRC-014", "question": "什么是控制采购？主要活动有哪些？", "standard_answer": "控制采购是管理采购关系、监督合同执行、进行必要变更和合同收尾的过程。主要活动：1)监督合同履行；2)管理变更；3)支付管理；4)采购审计；5)合同收尾。控制采购确保合同目标实现。", "keywords": ["控制采购", "合同履行", "变更管理", "支付", "采购审计", "合同收尾"], "process_group": "监控"},
        {"id": "PRC-015", "question": "什么是采购审计？", "standard_answer": "采购审计是对采购过程进行系统审查，识别成功经验和失败教训。审计内容：1)采购规划；2)招标过程；3)合同管理；4)供应商绩效。采购审计用于改进未来采购，是控制采购的工具，更新组织过程资产。", "keywords": ["采购审计", "经验教训", "招标", "合同管理", "供应商绩效"], "process_group": "监控"},
        {"id": "PRC-016", "question": "什么是合同变更控制系统？", "standard_answer": "合同变更控制系统是管理合同变更的程序，包括：1)文书工作；2)跟踪系统；3)争议解决程序；4)变更批准层次。合同变更控制系统是整体变更控制系统的一部分，确保合同变更受控。", "keywords": ["合同变更控制系统", "文书", "跟踪", "争议解决", "批准层次"], "process_group": "监控"},
        {"id": "PRC-017", "question": "什么是采购绩效审查？", "standard_answer": "采购绩效审查是结构化审查卖方履行合同情况的过程。审查内容：1)进度；2)质量；3)成本；4)范围。基于合同条款和卖方绩效数据，识别偏差和改进需求。采购绩效审查是控制采购的重要工具。", "keywords": ["采购绩效审查", "进度", "质量", "成本", "偏差", "改进"], "process_group": "监控"},
        {"id": "PRC-018", "question": "什么是检查和审计？", "standard_answer": "检查和审计是买方对卖方工作或产品进行验证的活动。检查：验证卖方是否完成合同要求的工作。审计：审查卖方过程是否符合要求。检查和审计用于控制采购，确保卖方交付符合合同要求。", "keywords": ["检查", "审计", "验证", "合同要求", "控制采购"], "process_group": "监控"},
        {"id": "PRC-019", "question": "什么是支付系统？", "standard_answer": "支付系统是买方向卖方支付合同款项的系统。支付基于合同条款和卖方交付成果，需经授权人员（如项目经理）审查批准。支付系统确保支付合规、及时，是控制采购的工具。通常由财务/会计部门执行。", "keywords": ["支付系统", "支付", "合同款项", "授权", "审查批准"], "process_group": "监控"},
        {"id": "PRC-020", "question": "什么是合同争议解决方法？", "standard_answer": "合同争议解决方法（按优先顺序）：1)谈判（直接协商）；2)调解（第三方调解）；3)仲裁（第三方裁决，有约束力）；4)诉讼（法院裁决）。合同应约定争议解决方式。优先选择低成本、维护关系的方式。", "keywords": ["争议解决", "谈判", "调解", "仲裁", "诉讼"], "process_group": "监控"},
        {"id": "PRC-021", "question": "什么是独立估算？", "standard_answer": "独立估算是买方自行或委托第三方对采购成本进行估算，用于与卖方报价对比。若报价与独立估算差异显著，需调查原因（范围理解不一致、报价错误、市场变化）。独立估算防止不合理报价，是建议书评价工具。", "keywords": ["独立估算", "买方估算", "报价对比", "差异", "合理性"], "process_group": "执行"},
        {"id": "PRC-022", "question": "什么是合同收尾？", "standard_answer": "合同收尾是完成和结算合同的过程，包括：1)确认所有工作和交付成果完成；2)结算支付；3)释放履约保函；4)归档合同文件；5)记录经验教训；6)更新组织过程资产。合同收尾是控制采购的输出。", "keywords": ["合同收尾", "结算", "支付", "归档", "经验教训"], "process_group": "监控"},
        {"id": "PRC-023", "question": "什么是提前终止合同？", "standard_answer": "提前终止合同是合同未完成前结束合同。原因：1)双方协商同意；2)违约（一方未履约）；3)便利终止（买方为便利终止）。提前终止需按合同条款处理，涉及赔偿、已交付成果处置、费用结算等。", "keywords": ["提前终止", "便利终止", "违约", "协商", "赔偿"], "process_group": "监控"},
        {"id": "PRC-024", "question": "什么是采购文件？包含哪些？", "standard_answer": "采购文件是用于征求卖方建议书的文件，包括：1)信息邀请书(RFI)；2)报价邀请书(RFQ)；3)建议邀请书(RFP)；4)招标书(IFB)。采购文件应清晰描述需求、条款、选择标准，便于卖方准确响应。", "keywords": ["采购文件", "RFI", "RFQ", "RFP", "IFB", "建议书"], "process_group": "规划"},
        {"id": "PRC-025", "question": "什么是履约保函？", "standard_answer": "履约保函是卖方提供的担保，确保履行合同义务。若卖方违约，买方可凭保函向担保方索赔。履约保函降低买方风险，常见于大型工程合同。保函金额通常为合同金额的5%-10%。是采购风险控制手段。", "keywords": ["履约保函", "担保", "违约", "索赔", "风险控制"], "process_group": "规划"},
        {"id": "PRC-026", "question": "什么是总寿命成本(TCO)？", "standard_answer": "总寿命成本(Total Cost of Ownership)是采购产品或服务全生命周期的总成本，包括：1)采购成本；2)运营成本；3)维护成本；4)培训成本；5)处置成本。采购决策应考虑TCO而非仅采购价格，避免低价高维护。", "keywords": ["TCO", "总寿命成本", "采购成本", "运营", "维护", "处置"], "process_group": "规划"},
        {"id": "PRC-027", "question": "什么是索赔管理？", "standard_answer": "索赔管理是处理合同一方因另一方未履行合同义务而提出的赔偿要求。包括：1)索赔记录；2)索赔分析；3)索赔谈判；4)争议解决。索赔管理需基于合同条款和事实证据，遵循合同变更控制系统。", "keywords": ["索赔管理", "赔偿", "记录", "分析", "谈判", "争议解决"], "process_group": "监控"},
        {"id": "PRC-028", "question": "什么是协议（合同）？其要素？", "standard_answer": "协议是买方和卖方之间具有法律效力的合同。要素：1)要约和承诺；2)对价；3)合法目的；4)具有法律能力的当事人。合同内容包括工作说明书、进度、价格、付款条款、变更程序、验收标准、终止条款等。", "keywords": ["协议", "合同", "要约", "承诺", "对价", "法律效力"], "process_group": "执行"},
        {"id": "PRC-029", "question": "什么是合格卖方清单？", "standard_answer": "合格卖方清单是组织维护的预先评估合格的卖方名单。基于历史绩效、资质审核等筛选。使用合格卖方清单可：1)缩短采购周期；2)降低采购风险；3)确保供应商质量。是实施采购的输入（选定的卖方）。", "keywords": ["合格卖方清单", "预评估", "供应商", "采购周期", "采购风险"], "process_group": "执行"},
        {"id": "PRC-030", "question": "项目采购管理的意义是什么？", "standard_answer": "项目采购管理意义：1)确保外部产品/服务及时获取；2)优化成本和质量；3)通过合同管理风险；4)建立供应商关系；5)支持项目目标实现。采购管理对依赖外部资源的项目至关重要，影响成本、进度和质量。", "keywords": ["采购管理", "意义", "外部资源", "成本", "风险", "供应商关系"], "process_group": "规划"},
    ]
}

# ============ 9. 项目风险管理 (Risk Management) ============
RISK = {
    "area": "项目风险管理",
    "area_en": "Risk Management",
    "records": [
        {"id": "RSK-001", "question": "项目风险管理包含哪些过程？", "standard_answer": "项目风险管理包含7个过程：1)规划风险管理；2)识别风险；3)实施定性风险分析；4)实施定量风险分析；5)规划风险应对；6)实施风险应对；7)监督风险。前5个规划，1个执行，1个监控。", "keywords": ["风险管理", "规划风险", "识别风险", "定性分析", "定量分析", "规划应对", "实施应对", "监督风险"], "process_group": "规划"},
        {"id": "RSK-002", "question": "什么是风险？风险三要素？", "standard_answer": "风险是不确定性对目标的影响。风险三要素：1)事件（可能发生什么）；2)概率（发生的可能性）；3)影响（对目标的影响）。风险包括威胁（负面影响）和机会（正面影响）。风险管理同时管理威胁和机会。", "keywords": ["风险", "三要素", "事件", "概率", "影响", "威胁", "机会"], "process_group": "规划"},
        {"id": "RSK-003", "question": "已知风险和未知风险的区别？", "standard_answer": "已知风险是已识别并分析的风险，可用应急储备应对。未知风险是未识别的风险，用管理储备应对。已知-未知：已识别但无法预测具体影响；未知-未知：完全未识别。风险管理的目标是尽可能将未知转为已知。", "keywords": ["已知风险", "未知风险", "应急储备", "管理储备", "识别"], "process_group": "规划"},
        {"id": "RSK-004", "question": "什么是风险登记册？包含哪些内容？", "standard_answer": "风险登记册记录已识别风险信息。内容：1)风险编号和描述；2)风险类别；3)概率和影响；4)风险优先级；5)风险责任人；6)应对策略；7)应对行动；8)状态。风险登记册是风险管理的核心文件，持续更新。", "keywords": ["风险登记册", "风险描述", "概率", "影响", "责任人", "应对策略"], "process_group": "规划"},
        {"id": "RSK-005", "question": "识别风险的方法有哪些？", "standard_answer": "识别风险方法：1)头脑风暴；2)德尔菲技术（专家匿名意见）；3)核对单；4)访谈；5)SWOT分析；6)假设和制约因素分析；7)文件审查；8)根本原因分析。需广泛邀请相关方参与识别。", "keywords": ["识别风险", "头脑风暴", "德尔菲", "SWOT", "核对单", "访谈"], "process_group": "规划"},
        {"id": "RSK-006", "question": "什么是德尔菲技术？", "standard_answer": "德尔菲技术是匿名收集专家意见达成共识的方法。流程：1)匿名征询专家意见；2)汇总反馈；3)再次征询；4)多轮迭代直至达成共识。优点：避免权威影响、匿名独立、达成共识。用于风险识别和预测。", "keywords": ["德尔菲", "匿名", "专家", "共识", "迭代"], "process_group": "规划"},
        {"id": "RSK-007", "question": "什么是SWOT分析？", "standard_answer": "SWOT分析是识别组织优势(S)、劣势(W)、机会(O)、威胁(T)的方法。在风险管理中：1)识别组织内部优势劣势；2)识别外部机会威胁；3)分析交叉策略（SO、WO、ST、WT）。SWOT帮助全面识别战略风险。", "keywords": ["SWOT", "优势", "劣势", "机会", "威胁", "战略风险"], "process_group": "规划"},
        {"id": "RSK-008", "question": "什么是定性风险分析？", "standard_answer": "定性风险分析是评估风险概率和影响、优先排序风险的过程。方法：1)概率和影响矩阵；2)风险数据质量评估；3)风险分类；4)风险紧迫性评估。定性分析快速筛选风险，为定量分析和应对规划提供依据。", "keywords": ["定性分析", "概率影响矩阵", "优先排序", "风险分类", "紧迫性"], "process_group": "规划"},
        {"id": "RSK-009", "question": "什么是概率和影响矩阵？", "standard_answer": "概率和影响矩阵是将风险概率和影响交叉形成的网格，用于风险优先级排序。概率和影响各分多级（如1-5），交叉点表示风险等级（低、中、高）。矩阵帮助识别需重点应对的风险，是定性分析的核心工具。", "keywords": ["概率影响矩阵", "概率", "影响", "优先级", "风险等级"], "process_group": "规划"},
        {"id": "RSK-010", "question": "什么是定量风险分析？", "standard_answer": "定量风险分析是量化风险对项目目标影响的过程。方法：1)敏感性分析（龙卷风图）；2)预期货币价值(EMV)分析；3)决策树分析；4)蒙特卡洛模拟；5)影响图。定量分析提供风险量化数据，支持决策。", "keywords": ["定量分析", "敏感性分析", "EMV", "决策树", "蒙特卡洛"], "process_group": "规划"},
        {"id": "RSK-011", "question": "什么是蒙特卡洛模拟？", "standard_answer": "蒙特卡洛模拟是通过计算机多次随机抽样模拟项目结果的方法。输入：各活动持续时间/成本的概率分布。输出：项目总持续时间/成本的概率分布。用于定量风险分析，评估项目在预算内按时完成的概率。", "keywords": ["蒙特卡洛", "模拟", "随机抽样", "概率分布", "定量分析"], "process_group": "规划"},
        {"id": "RSK-012", "question": "什么是预期货币价值(EMV)？", "standard_answer": "预期货币价值(EMV)=概率×影响。EMV用于量化风险的平均货币影响。例如：风险概率20%，影响-10万元，EMV=-2万元。EMV常用于决策树分析，选择EMV最大的方案。EMV适用于重复性决策，单次决策需谨慎。", "keywords": ["EMV", "预期货币价值", "概率", "影响", "决策树"], "process_group": "规划"},
        {"id": "RSK-013", "question": "什么是决策树分析？", "standard_answer": "决策树分析是利用决策树模型量化分析决策方案的方法。计算各路径EMV=概率×影响，选择EMV最大的决策路径。决策树包含决策节点（方形）和机会节点（圆形）。用于风险应对方案选择和决策。", "keywords": ["决策树", "EMV", "决策节点", "机会节点", "决策路径"], "process_group": "规划"},
        {"id": "RSK-014", "question": "什么是敏感性分析（龙卷风图）？", "standard_answer": "敏感性分析是确定哪些风险对项目目标影响最大的方法。龙卷风图按影响大小排序各风险因素，形似龙卷风。位于顶部的风险影响最大，需优先应对。敏感性分析帮助识别关键风险，是定量分析工具。", "keywords": ["敏感性分析", "龙卷风图", "影响", "关键风险", "定量分析"], "process_group": "规划"},
        {"id": "RSK-015", "question": "威胁的四种应对策略？", "standard_answer": "威胁（负面风险）四种应对策略：1)规避：消除威胁或保护项目免受影响（如改变计划）；2)转移：将威胁责任转移给第三方（如保险、外包）；3)减轻：降低概率或影响；4)接受：承认风险，不主动应对（主动接受设应急储备）。", "keywords": ["威胁应对", "规避", "转移", "减轻", "接受"], "process_group": "规划"},
        {"id": "RSK-016", "question": "机会的四种应对策略？", "standard_answer": "机会（正面风险）四种应对策略：1)开拓：确保机会实现（如分配最好资源）；2)分享：将机会责任分配给第三方共享收益；3)提高：提高概率或正面影响；4)接受：承认机会但不主动追求。", "keywords": ["机会应对", "开拓", "分享", "提高", "接受"], "process_group": "规划"},
        {"id": "RSK-017", "question": "什么是应急应对策略？", "standard_answer": "应急应对策略是针对特定风险设计的、仅在特定条件（触发条件）发生时才执行的应对。需要：1)定义触发条件；2)制定应对方案；3)分配责任人；4)监控触发条件。适用于需快速响应的风险。", "keywords": ["应急应对", "触发条件", "应对方案", "责任人", "快速响应"], "process_group": "规划"},
        {"id": "RSK-018", "question": "什么是风险责任人？", "standard_answer": "风险责任人是负责管理特定风险的项目团队成员。职责：1)监控风险状态；2)实施风险应对；3)报告风险变化；4)建议应对调整。每个已识别风险都应指定责任人，明确风险管理的责任归属。", "keywords": ["风险责任人", "管理风险", "监控", "应对", "责任归属"], "process_group": "规划"},
        {"id": "RSK-019", "question": "什么是风险紧迫性评估？", "standard_answer": "风险紧迫性评估是评估风险是否需近期应对的方法。考虑因素：1)风险发生时间；2)应对所需时间；3)风险症状（触发条件）；4)风险等级。紧迫性高的风险需优先处理，纳入近期应对计划。", "keywords": ["风险紧迫性", "发生时间", "应对时间", "触发条件", "风险等级"], "process_group": "规划"},
        {"id": "RSK-020", "question": "什么是实施风险应对？", "standard_answer": "实施风险应对是执行商定的风险应对计划的过程。包括：1)执行规避、转移、减轻、接受策略；2)分配应急储备；3)执行应急计划；4)监控应对效果。实施风险应对属于执行过程组，确保应对落地。", "keywords": ["实施风险应对", "执行", "应急计划", "应急储备", "应对效果"], "process_group": "执行"},
        {"id": "RSK-021", "question": "什么是监督风险？主要活动？", "standard_answer": "监督风险是监督已识别风险、识别新风险、执行风险应对计划并评估有效性的过程。活动：1)跟踪已识别风险；2)识别新风险；3)评估应对有效性；4)更新风险登记册；5)风险审计；6)风险再评估。", "keywords": ["监督风险", "跟踪", "新风险", "应对有效性", "风险审计", "再评估"], "process_group": "监控"},
        {"id": "RSK-022", "question": "什么是风险审计？", "standard_answer": "风险审计是检查和记录风险应对有效性的过程。审计内容：1)风险应对措施是否执行；2)应对是否有效；3)风险管理过程是否遵循。风险审计由项目经理或独立审计师进行，用于改进风险管理。", "keywords": ["风险审计", "应对有效性", "过程遵循", "改进", "检查记录"], "process_group": "监控"},
        {"id": "RSK-023", "question": "什么是风险再评估？", "standard_answer": "风险再评估是定期重新评估风险状态的过程。包括：1)识别新风险（之前未识别）；2)重新评估已识别风险的概率和影响；3)关闭已不存在的风险；4)更新风险优先级。风险再评估在监督风险过程中进行。", "keywords": ["风险再评估", "新风险", "重新评估", "关闭风险", "优先级"], "process_group": "监控"},
        {"id": "RSK-024", "question": "什么是次生风险？", "standard_answer": "次生风险是实施风险应对策略直接导致的新风险。例如：转移风险给供应商，可能产生供应商违约风险。规划风险应对时需识别次生风险，制定应对措施，避免应对本身带来新问题。", "keywords": ["次生风险", "风险应对", "导致", "新风险", "应对措施"], "process_group": "规划"},
        {"id": "RSK-025", "question": "什么是弹回计划？", "standard_answer": "弹回计划是风险应对策略无效时的备用计划。当主应对策略未能达到预期效果时，启动弹回计划。弹回计划针对关键风险制定，确保有备选方案，降低应对失败的影响。弹回计划需在规划阶段制定。", "keywords": ["弹回计划", "备用计划", "应对无效", "备选方案", "关键风险"], "process_group": "规划"},
        {"id": "RSK-026", "question": "什么是风险分类？", "standard_answer": "风险分类是按风险来源、类型、影响领域等对风险进行分组的方法。常见分类：1)按来源（技术、外部、组织、项目管理）；2)按影响领域（范围、进度、成本、质量）；3)按相关方。分类帮助识别风险模式和集中应对。", "keywords": ["风险分类", "来源", "类型", "影响领域", "风险模式"], "process_group": "规划"},
        {"id": "RSK-027", "question": "什么是风险数据质量评估？", "standard_answer": "风险数据质量评估是评估风险数据准确性和可靠性的方法。评估维度：1)数据完整性；2)数据质量；3)数据准确性；4)数据可靠性。数据质量低的风险分析结果不可靠，需收集更多数据再分析。", "keywords": ["风险数据质量", "完整性", "准确性", "可靠性", "数据收集"], "process_group": "规划"},
        {"id": "RSK-028", "question": "什么是风险管理计划？包含哪些内容？", "standard_answer": "风险管理计划描述如何实施项目风险管理活动。包含：1)方法论；2)角色和职责；3)预算；4)时间安排；5)风险类别（RBS）；6)概率和影响定义；7)概率影响矩阵；8)修订的利益方风险容忍度；9)报告格式；10)跟踪。", "keywords": ["风险管理计划", "方法论", "角色职责", "RBS", "概率影响矩阵"], "process_group": "规划"},
        {"id": "RSK-029", "question": "什么是风险报告？", "standard_answer": "风险报告汇总项目风险信息，内容：1)整体项目风险暴露；2)主要个别风险；3)风险趋势；4)应对进展；5)定量分析结果。风险报告随项目进展定期更新，向相关方沟通风险状态。", "keywords": ["风险报告", "风险暴露", "个别风险", "趋势", "应对进展"], "process_group": "监控"},
        {"id": "RSK-030", "question": "项目风险管理的意义是什么？", "standard_answer": "项目风险管理意义：1)识别和应对威胁，提高项目成功率；2)识别和利用机会；3)减少意外和返工；4)优化应急储备；5)支持决策；6)提升相关方信心。风险管理是主动管理，将不确定性转化为可控因素。", "keywords": ["风险管理", "意义", "威胁", "机会", "应急储备", "决策"], "process_group": "规划"},
    ]
}

# ============ 10. 项目相关方管理 (Stakeholder Management) ============
STAKEHOLDER = {
    "area": "项目相关方管理",
    "area_en": "Stakeholder Management",
    "records": [
        {"id": "STK-001", "question": "项目相关方管理包含哪些过程？", "standard_answer": "项目相关方管理包含4个过程：1)识别相关方；2)规划相关方参与；3)管理相关方参与；4)监督相关方参与。1个启动，1个规划，1个执行，1个监控。相关方管理确保项目相关方期望得到管理。", "keywords": ["相关方管理", "识别相关方", "规划参与", "管理参与", "监督参与"], "process_group": "启动"},
        {"id": "STK-002", "question": "什么是相关方？", "standard_answer": "相关方是能影响项目决策、活动或结果的个人、群体或组织，或受项目决策、活动或结果影响的个人、群体或组织。包括客户、发起人、项目团队、供应商、政府、社区等。相关方管理是项目成功的关键。", "keywords": ["相关方", "影响", "个人", "群体", "组织"], "process_group": "启动"},
        {"id": "STK-003", "question": "什么是识别相关方？主要活动？", "standard_answer": "识别相关方是定期识别项目相关方、分析和记录其利益、参与度、相互依赖、影响力和对项目成功影响的过程。主要活动：1)识别相关方；2)分析和记录相关信息；3)更新相关方登记册。属于启动过程组。", "keywords": ["识别相关方", "利益", "参与度", "影响力", "相关方登记册"], "process_group": "启动"},
        {"id": "STK-004", "question": "什么是相关方登记册？包含哪些内容？", "standard_answer": "相关方登记册记录已识别相关方的信息。内容：1)身份信息（姓名、组织、职位、联系方式）；2)评估信息（需求、期望、影响力、利益阶段）；3)相关方分类（内部/外部、支持者/反对者、权力/利益）。持续更新。", "keywords": ["相关方登记册", "身份信息", "评估信息", "分类", "影响力"], "process_group": "启动"},
        {"id": "STK-005", "question": "什么是权力/利益方格？", "standard_answer": "权力/利益方格是按相关方权力（影响力）和利益（关注度）分类的矩阵。四象限：1)高权力高利益-重点管理；2)高权力低利益-令其满意；3)低权力高利益-随时告知；4)低权力低利益-监督。帮助制定参与策略。", "keywords": ["权力利益方格", "权力", "利益", "重点管理", "令其满意", "随时告知", "监督"], "process_group": "规划"},
        {"id": "STK-006", "question": "什么是权力/影响方格？", "standard_answer": "权力/影响方格是按相关方权力和影响力分类的矩阵。与权力/利益方格类似，但用\"影响力\"替代\"利益\"。四象限：1)高权力高影响-密切管理；2)高权力低影响-令其满意；3)低权力高影响-随时告知；4)低权力低影响-监督。", "keywords": ["权力影响方格", "权力", "影响力", "密切管理", "令其满意"], "process_group": "规划"},
        {"id": "STK-007", "question": "什么是影响/作用方格？", "standard_answer": "影响/作用方格是按相关方在项目中的影响和作用（参与能力）分类的矩阵。四象限：1)高影响高作用-密切管理；2)高影响低作用-令其满意；3)低影响高作用-随时告知；4)低影响低作用-监督。是相关方分析工具。", "keywords": ["影响作用方格", "影响", "作用", "参与能力", "密切管理"], "process_group": "规划"},
        {"id": "STK-008", "question": "什么是凸显模型？", "standard_answer": "凸显模型根据相关方的权力、紧迫性和合法性三个属性分类。三个属性都具备为\"决定性\"相关方；具备两个为\"期待性\"；具备一个为\"潜伏性\"。凸显模型帮助识别需优先管理的关键相关方。", "keywords": ["凸显模型", "权力", "紧迫性", "合法性", "决定性", "期待性", "潜伏性"], "process_group": "规划"},
        {"id": "STK-009", "question": "什么是规划相关方参与？", "standard_answer": "规划相关方参与是制定促进相关方有效参与项目决策和执行的策略和行动的过程。输出：相关方参与计划。基于相关方需求、期望、利益和潜在影响制定参与策略。属于规划过程组。", "keywords": ["规划相关方参与", "策略", "相关方参与计划", "需求", "期望"], "process_group": "规划"},
        {"id": "STK-010", "question": "什么是相关方参与计划？", "standard_answer": "相关方参与计划是确定促进相关方有效参与项目决策和执行的策略和行动。内容：相关方参与评估矩阵、参与策略、沟通需求、变更管理。相关方参与计划是项目管理计划组成部分，需随相关方变化更新。", "keywords": ["相关方参与计划", "参与策略", "沟通需求", "评估矩阵", "变更管理"], "process_group": "规划"},
        {"id": "STK-011", "question": "什么是管理相关方参与？主要活动？", "standard_answer": "管理相关方参与是与相关方进行沟通和协作，满足其需求期望，处理问题并促进参与的过程。活动：1)沟通相关方参与计划；2)管理相关方期望；3)处理问题和风险；4)解决冲突；5)提升参与度。属于执行过程组。", "keywords": ["管理相关方参与", "沟通", "协作", "期望", "冲突", "参与度"], "process_group": "执行"},
        {"id": "STK-012", "question": "什么是监督相关方参与？主要活动？", "standard_answer": "监督相关方参与是监督项目相关方关系并通过修改参与策略和计划引导相关方参与的过程。活动：1)评估相关方参与度变化；2)识别新相关方；3)调整参与策略；4)更新相关方登记册和参与计划。属于监控过程组。", "keywords": ["监督相关方参与", "评估", "新相关方", "调整策略", "参与计划"], "process_group": "监控"},
        {"id": "STK-013", "question": "相关方参与度评估矩阵的五类参与度？", "standard_answer": "相关方参与度评估矩阵五类参与度：1)不了解(Unaware)：不知晓项目；2)抵制(Resistant)：知晓但抵制；3)中立(Neutral)：知晓但不支持不反对；4)支持(Supportive)：知晓并支持；5)领导(Leading)：积极推动。矩阵对比当前与期望参与度。", "keywords": ["参与度评估矩阵", "不了解", "抵制", "中立", "支持", "领导"], "process_group": "规划"},
        {"id": "STK-014", "question": "如何识别相关方？方法有哪些？", "standard_answer": "识别相关方方法：1)相关方分析（识别和分类）；2)文件审查（商业论证、项目章程、协议）；3)专家判断；4)数据收集（问卷、头脑风暴）；5)数据表现（权力利益方格、凸显模型）。需定期反复识别。", "keywords": ["识别相关方", "相关方分析", "文件审查", "专家判断", "权力利益方格"], "process_group": "启动"},
        {"id": "STK-015", "question": "什么是相关方分析？步骤？", "standard_answer": "相关方分析是系统地收集和分析相关方信息的过程。步骤：1)识别相关方信息（需求、期望、利益）；2)识别相关方间关系；3)分类（权力/利益方格）；4)评估影响和优先级。相关方分析是识别和规划参与的基础。", "keywords": ["相关方分析", "信息", "关系", "分类", "优先级"], "process_group": "启动"},
        {"id": "STK-016", "question": "什么是相关方参与中的冲突管理？", "standard_answer": "相关方参与中冲突管理是处理相关方间分歧和期望冲突的过程。方法：1)合作/解决问题（双赢，最佳）；2)妥协/调解；3)缓和/包容；4)撤退/回避；5)强迫/命令。管理相关方参与过程需解决冲突。", "keywords": ["冲突管理", "相关方", "合作", "妥协", "缓和", "强迫"], "process_group": "执行"},
        {"id": "STK-017", "question": "什么是相关方沟通？原则？", "standard_answer": "相关方沟通是向相关方传递项目信息和倾听其反馈的过程。原则：1)针对不同相关方定制沟通内容和方式；2)及时透明；3)双向沟通；4)管理期望；5)记录沟通历史。相关方沟通是管理参与的核心。", "keywords": ["相关方沟通", "定制", "透明", "双向沟通", "管理期望"], "process_group": "执行"},
        {"id": "STK-018", "question": "什么是相关方期望管理？", "standard_answer": "相关方期望管理是识别、分析和影响相关方对项目的期望，使其与项目目标一致的过程。方法：1)明确期望；2)管理期望（避免过度承诺）；3)及时沟通进展；4)处理期望差距；5)建立信任。期望管理贯穿项目始终。", "keywords": ["期望管理", "期望", "沟通", "信任", "项目目标"], "process_group": "执行"},
        {"id": "STK-019", "question": "什么是相关方参与中的政治意识？", "standard_answer": "政治意识是理解组织内权力结构、利益关系和影响网络的能力。在相关方管理中，政治意识帮助：1)识别关键决策者；2)理解相关方间关系；3)避免政治风险；4)有效施加影响。政治意识是项目经理的重要软技能。", "keywords": ["政治意识", "权力结构", "利益关系", "决策者", "影响"], "process_group": "执行"},
        {"id": "STK-020", "question": "什么是相关方参与中的协商？", "standard_answer": "协商是项目经理与相关方就需求、资源、变更等进行讨论达成共识的过程。协商原则：1)寻求双赢；2)基于事实和数据；3)理解对方立场；4)保持灵活；5)维护关系。协商是管理相关方参与的重要技能。", "keywords": ["协商", "相关方", "双赢", "事实", "共识"], "process_group": "执行"},
        {"id": "STK-021", "question": "如何应对抵制型相关方？", "standard_answer": "应对抵制型相关方：1)了解抵制原因；2)倾听其担忧；3)提供信息和数据消除误解；4)让其参与决策增加认同感；5)展示项目对其的利益；6)寻求高层支持；7)调整方案满足合理需求。目标是将其转为支持或中立。", "keywords": ["抵制型相关方", "抵制", "倾听", "参与决策", "高层支持"], "process_group": "执行"},
        {"id": "STK-022", "question": "什么是相关方优先级排序？", "standard_answer": "相关方优先级排序是根据相关方权力、利益、影响力、紧迫性等对相关方进行排序，确定管理优先级。高权力高利益相关方优先管理。优先级排序帮助项目经理合理分配精力，聚焦关键相关方。", "keywords": ["优先级排序", "权力", "利益", "影响力", "关键相关方"], "process_group": "启动"},
        {"id": "STK-023", "question": "什么是相关方参与中的问题管理？", "standard_answer": "相关方参与中的问题管理是识别、记录、跟踪和解决相关方提出的问题。使用问题日志记录问题、责任人、解决期限。问题管理确保相关方问题得到及时处理，维护相关方关系和项目顺利进行。", "keywords": ["问题管理", "相关方", "问题日志", "责任人", "解决"], "process_group": "执行"},
        {"id": "STK-024", "question": "什么是相关方变更管理？", "standard_answer": "相关方变更管理是处理项目执行中相关方变化的过程。变化包括：新相关方出现、相关方权力/利益变化、相关方立场变化。需：1)更新相关方登记册；2)调整参与策略；3)修订相关方参与计划；4)通知相关方。", "keywords": ["相关方变更", "新相关方", "权力变化", "立场变化", "参与计划"], "process_group": "监控"},
        {"id": "STK-025", "question": "什么是相关方参与的基准？", "standard_answer": "相关方参与基准是相关方参与计划中确定的期望相关方参与水平。用于监督相关方参与时比较实际与期望参与度，识别差距并采取行动。相关方参与基准是监督相关方参与过程的依据。", "keywords": ["参与基准", "期望参与", "实际参与", "差距", "监督"], "process_group": "规划"},
        {"id": "STK-026", "question": "什么是相关方参与中的情商应用？", "standard_answer": "相关方参与中应用情商：1)理解相关方情绪和需求；2)同理心建立信任；3)管理自身情绪；4)适应不同相关方沟通风格；5)处理敏感问题。情商帮助建立良好相关方关系，提升参与效果。", "keywords": ["情商", "相关方", "同理心", "信任", "沟通风格"], "process_group": "执行"},
        {"id": "STK-027", "question": "什么是相关方参与中的文化意识？", "standard_answer": "文化意识是理解不同文化背景相关方的价值观、沟通方式、决策习惯。在相关方管理中，文化意识帮助：1)避免文化误解；2)选择合适沟通方式；3)尊重文化差异；4)建立跨文化信任。是国际化项目的重要能力。", "keywords": ["文化意识", "相关方", "价值观", "沟通方式", "跨文化"], "process_group": "执行"},
        {"id": "STK-028", "question": "什么是发起人在相关方管理中的角色？", "standard_answer": "发起人在相关方管理中角色：1)提供项目方向和资源；2)清除组织障碍；3)支持项目经理决策；4)管理高层相关方；5)签署项目章程；6)参与阶段关口审查。发起人是项目最重要的内部相关方之一。", "keywords": ["发起人", "相关方", "资源", "障碍", "高层相关方", "项目章程"], "process_group": "启动"},
        {"id": "STK-029", "question": "什么是相关方参与中的反馈机制？", "standard_answer": "反馈机制是收集相关方对项目进展和决策意见的系统。包括：1)定期调查；2)会议反馈；3)一对一沟通；4)匿名反馈渠道。反馈机制帮助项目经理了解相关方满意度和期望变化，及时调整参与策略。", "keywords": ["反馈机制", "相关方", "调查", "满意度", "参与策略"], "process_group": "监控"},
        {"id": "STK-030", "question": "项目相关方管理的意义是什么？", "standard_answer": "项目相关方管理意义：1)获得相关方支持减少阻力；2)管理相关方期望避免冲突；3)整合相关方需求提升项目价值；4)促进相关方参与提高项目成功率；5)维护长期合作关系。相关方管理是项目成功的关键因素。", "keywords": ["相关方管理", "意义", "支持", "期望", "参与", "成功"], "process_group": "启动"},
    ]
}

ALL_AREAS = [INTEGRATION, SCOPE, SCHEDULE, COST, QUALITY,
             RESOURCE, COMMUNICATIONS, PROCUREMENT, RISK, STAKEHOLDER]


def main():
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    total = 0
    for area_data in ALL_AREAS:
        filename = area_data["area_en"].lower().replace(" ", "_") + ".json"
        filepath = os.path.join(OUTPUT_DIR, filename)
        with open(filepath, "w", encoding="utf-8") as f:
            json.dump(area_data, f, ensure_ascii=False, indent=2)
        count = len(area_data["records"])
        total += count
        print(f"已生成 {area_data['area']} ({filename}): {count} 条")
    print(f"\n本次共生成 {len(ALL_AREAS)} 个知识领域，{total} 条记录")


if __name__ == "__main__":
    main()
